public.fn_club_opening_checklist_complet.def:
CREATE OR REPLACE FUNCTION public.fn_club_opening_checklist_complete(p_club_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_club public.clubs%ROWTYPE;
  v_row public.club_opening_checklists%ROWTYPE;
  v_skipped text[] := '{}'::text[];
  v_unfinished text[] := '{}'::text[];
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Sign In To Finish The Opening Checklist' USING ERRCODE='42501'; END IF;
  SELECT * INTO v_club FROM public.clubs c WHERE c.id=p_club_id FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Club Not Found' USING ERRCODE='P0002'; END IF;
  IF v_club.owner_id IS DISTINCT FROM v_uid THEN RAISE EXCEPTION 'Only The Club Owner Can Finish The Opening Checklist' USING ERRCODE='42501'; END IF;
  SELECT * INTO v_row FROM public.club_opening_checklists k WHERE k.club_id=p_club_id FOR UPDATE;
  IF FOUND AND v_row.completed_at IS NOT NULL THEN
    RETURN jsonb_build_object('clubId',p_club_id,'completedAt',v_row.completed_at,'skippedTaskIds',to_jsonb(v_row.skipped_task_ids));
  END IF;
  IF NOT COALESCE(public.fn_club_opening_checklist_eligible(p_club_id),false) THEN RAISE EXCEPTION 'This Club Has No Opening Checklist' USING ERRCODE='55000'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.club_opening_setups s WHERE s.club_id=p_club_id) THEN RAISE EXCEPTION 'Complete The Opening Setup Wizard First' USING ERRCODE='55000'; END IF;
  v_skipped:=COALESCE(v_row.skipped_task_ids,'{}'::text[]);
  IF NOT('identity'=ANY(v_skipped)) AND NOT(
    (NULLIF(btrim(COALESCE(v_club.logo_url,'')),'') IS NOT NULL AND v_club.logo_url !~* '(^|/)club-logos/preset-[0-9]+[.](webp|png|jpe?g)([?#].*)?$')
    OR (NULLIF(btrim(COALESCE(v_club.avatar_url,'')),'') IS NOT NULL AND v_club.avatar_url !~* '(^|/)club-logos/preset-[0-9]+[.](webp|png|jpe?g)([?#].*)?$')
  ) THEN v_unfinished:=array_append(v_unfinished,'identity'); END IF;
  IF NOT('tagline'=ANY(v_skipped)) AND NULLIF(btrim(COALESCE(v_club.tagline,'')),'') IS NULL THEN v_unfinished:=array_append(v_unfinished,'tagline'); END IF;
  IF NOT('nlh'=ANY(v_skipped)) AND NOT EXISTS(SELECT 1 FROM public.tables t WHERE t.club_id=p_club_id AND lower(COALESCE(t.game_variant,'')) IN('nlh','short_deck','pineapple') AND lower(COALESCE(t.status,'')) NOT IN('deleted','archived')) THEN v_unfinished:=array_append(v_unfinished,'nlh'); END IF;
  IF NOT('plo'=ANY(v_skipped)) AND NOT EXISTS(SELECT 1 FROM public.tables t WHERE t.club_id=p_club_id AND lower(COALESCE(t.game_variant,'')) LIKE 'plo%' AND lower(COALESCE(t.status,'')) NOT IN('deleted','archived')) THEN v_unfinished:=array_append(v_unfinished,'plo'); END IF;
  IF NOT('limit'=ANY(v_skipped)) AND NOT EXISTS(SELECT 1 FROM public.tables t WHERE t.club_id=p_club_id AND (lower(COALESCE(t.game_variant,'')) IN('flh','flo8') OR lower(COALESCE(t.game_variant,'')) LIKE 'limit%') AND lower(COALESCE(t.status,'')) NOT IN('deleted','archived')) THEN v_unfinished:=array_append(v_unfinished,'limit'); END IF;
  IF NOT('mtt'=ANY(v_skipped)) AND NOT EXISTS(SELECT 1 FROM public.tournaments t WHERE t.club_id=p_club_id AND t.format_contract IN('mtt-v1','mtt-v2')) THEN v_unfinished:=array_append(v_unfinished,'mtt'); END IF;
  IF NOT('spin'=ANY(v_skipped)) AND NOT EXISTS(SELECT 1 FROM public.tournaments t WHERE t.club_id=p_club_id AND t.format_contract='spin-v1') THEN v_unfinished:=array_append(v_unfinished,'spin'); END IF;
  IF NOT('heads-up'=ANY(v_skipped)) AND NOT EXISTS(SELECT 1 FROM public.tournaments t WHERE t.club_id=p_club_id AND t.format_contract='sng-v1') THEN v_unfinished:=array_append(v_unfinished,'heads-up'); END IF;
  IF NOT('first-player'=ANY(v_skipped)) AND NOT EXISTS(SELECT 1 FROM public.club_members m WHERE m.club_id=p_club_id AND m.user_id IS DISTINCT FROM v_club.owner_id AND m.status::text IN('active','approved')) THEN v_unfinished:=array_append(v_unfinished,'first-player'); END IF;
  IF NOT('first-agent'=ANY(v_skipped)) AND NOT EXISTS(SELECT 1 FROM public.agents a WHERE a.club_id=p_club_id AND lower(COALESCE(a.status,'active'))<>'inactive') THEN v_unfinished:=array_append(v_unfinished,'first-agent'); END IF;
  IF cardinality(v_unfinished)>0 THEN RAISE EXCEPTION 'Finish Or Skip Every Opening Checklist Step: %',array_to_string(v_unfinished,', ') USING ERRCODE='55000'; END IF;
  INSERT INTO public.club_opening_checklists AS k(club_id,completed_at,completed_by) VALUES(p_club_id,now(),v_uid)
  ON CONFLICT(club_id) DO UPDATE SET completed_at=now(),completed_by=v_uid,updated_at=now() WHERE k.completed_at IS NULL;
  SELECT * INTO v_row FROM public.club_opening_checklists k WHERE k.club_id=p_club_id;
  RETURN jsonb_build_object('clubId',p_club_id,'completedAt',v_row.completed_at,'skippedTaskIds',to_jsonb(v_row.skipped_task_ids));
END
$function$

public.fn_club_owner_has_a_player_wallet.def:
CREATE OR REPLACE FUNCTION public.fn_club_owner_has_a_player_wallet()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_previous text := COALESCE(current_setting('app.club_membership_source', true), '');
BEGIN
  -- THE ARENA BELONGS TO THE SYSTEM (2026-09-30): only a chip club gives its
  -- owner a player wallet. Diamond participation is automatic and holds no
  -- wallet (the arena's membership guard refuses any other row), so for the
  -- Diamond Arena this trigger would refuse every change of owner at commit.
  IF NEW.owner_id IS NULL OR COALESCE(NEW.is_union, false) OR NEW.asset IS DISTINCT FROM 'chips' THEN RETURN NULL; END IF;
  IF TG_OP = 'UPDATE' AND OLD.owner_id IS NOT DISTINCT FROM NEW.owner_id THEN
    RETURN NULL;
  END IF;

  IF EXISTS (SELECT 1 FROM public.club_members cm
              WHERE cm.club_id = NEW.id AND cm.user_id = NEW.owner_id) THEN
    UPDATE public.club_members
       SET status = CASE WHEN COALESCE(status, 'active') IN ('active', 'approved') THEN status ELSE 'active' END,
           role   = CASE WHEN role IN ('owner', 'co_owner') THEN role ELSE 'owner' END,
           updated_at = now()
     WHERE club_id = NEW.id AND user_id = NEW.owner_id
       AND (COALESCE(status, 'active') NOT IN ('active', 'approved') OR role NOT IN ('owner', 'co_owner'));
    RETURN NULL;
  END IF;

  PERFORM set_config('app.club_membership_source', 'club_owner_create', true);
  PERFORM set_config('app.club_role_change', 'on', true);
  BEGIN
    INSERT INTO public.club_members (club_id, user_id, role, status, chip_balance)
    VALUES (NEW.id, NEW.owner_id, 'owner', 'active', 0)
    ON CONFLICT (club_id, user_id) DO NOTHING;
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('app.club_membership_source', v_previous, true);
    RAISE;
  END;
  PERFORM set_config('app.club_membership_source', v_previous, true);
  RETURN NULL;
END;
$function$

public.fn_club_staff_notice_role_event().def:
CREATE OR REPLACE FUNCTION public.fn_club_staff_notice_role_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
 IF TG_TABLE_NAME='clubs' THEN
  PERFORM public.fn_sync_club_staff_notice_group(NEW.id); RETURN NULL;
 END IF;
 IF TG_OP<>'DELETE' THEN PERFORM public.fn_sync_club_staff_notice_group(NEW.club_id); END IF;
 IF TG_OP='DELETE' OR (TG_OP='UPDATE' AND OLD.club_id IS DISTINCT FROM NEW.club_id) THEN PERFORM public.fn_sync_club_staff_notice_group(OLD.club_id); END IF;
 RETURN NULL;
END $function$

public.fn_clubs_lobby_message_keeps_its_.def:
CREATE OR REPLACE FUNCTION public.fn_clubs_lobby_message_keeps_its_own_books()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  -- Whitespace is not a message. One rule, applied before any writer's own.
  IF NEW.lobby_message IS NOT NULL AND btrim(NEW.lobby_message) = '' THEN
    NEW.lobby_message := NULL;
  END IF;

  IF TG_OP = 'INSERT' THEN
    NEW.lobby_message_updated_at := CASE
      WHEN NEW.lobby_message IS NULL THEN NULL
      ELSE COALESCE(NEW.lobby_message_updated_at, now())
    END;
    RETURN NEW;
  END IF;

  IF NEW.lobby_message IS DISTINCT FROM OLD.lobby_message THEN
    NEW.lobby_message_updated_at := CASE
      WHEN NEW.lobby_message IS NULL THEN NULL
      ELSE now()
    END;
    -- A writer that bumped the revision in this same statement is left alone.
    -- One that forgot is corrected, which is the difference between a message
    -- rewritten from Club Settings reaching a player who dismissed the last
    -- one, and that message never reaching them at all.
    IF NEW.message_revision IS NOT DISTINCT FROM OLD.message_revision THEN
      NEW.message_revision := COALESCE(OLD.message_revision, 0) + 1;
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

public.fn_deliver_accounting_invoice(p_i.def:
CREATE OR REPLACE FUNCTION public.fn_deliver_accounting_invoice(p_invoice_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_variable
DECLARE inv public.settlement_invoices%ROWTYPE; sender uuid; issuer_name text; recipient_name text;
 issuer_kind text; issuer_id uuid; recipient_id uuid; scope_id uuid; page_id uuid; users uuid[]; issuer_users uuid[]; recipient_users uuid[];
 person uuid; conv uuid; msg uuid; note uuid; body text; meta jsonb; count_sent int:=0; n int; line record; cashier public.accounting_cashier_events%ROWTYPE; cashier_payload jsonb; correction public.accounting_correction_documents%ROWTYPE; correction_payload jsonb; credit_change public.accounting_credit_change_documents_v1%ROWTYPE; credit_operation public.accounting_credit_reduction_operations_v1%ROWTYPE; credit_payload jsonb;
BEGIN
 SELECT * INTO inv FROM public.settlement_invoices WHERE id=p_invoice_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'accounting_invoice_missing' USING ERRCODE='23514'; END IF;
 IF public.fn_accounting_correction_is_unverified(inv.id)
 THEN RAISE EXCEPTION 'historical_correction_document_unverified' USING ERRCODE='23514';END IF;
 IF inv.net_amount IS NULL OR inv.net_amount::text IN('NaN','Infinity','-Infinity') OR inv.net_amount<>round(inv.net_amount,2)
 THEN RAISE EXCEPTION 'invalid_invoice_amount' USING ERRCODE='23514'; END IF;
 -- Owner rule (2026-10-15): only cashout documents reach the messenger (the player's request
 -- reaches their agent, the approval reaches the player). Every other invoice is recorded in
 -- transaction history only and marked delivered so the weekly close is satisfied.
 IF inv.invoice_type IS DISTINCT FROM 'cashier_cashout' THEN
  IF inv.invoice_number IS NULL THEN
   UPDATE public.settlement_invoices SET invoice_number=public.fn_accounting_next_invoice_number() WHERE id=inv.id RETURNING invoice_number INTO inv.invoice_number;
  END IF;
  UPDATE public.settlement_invoices SET message_sent=true,message_sent_at=COALESCE(message_sent_at,now()) WHERE id=inv.id;
  RETURN jsonb_build_object('success',true,'invoice_id',inv.id,'delivered',0,'new_deliveries',0);
 END IF;
 issuer_kind:=inv.from_entity_type; issuer_id:=inv.from_entity_id::uuid; recipient_id:=inv.to_entity_id::uuid;
 scope_id:=COALESCE(inv.club_id,issuer_id);
 IF inv.invoice_type='credit_limit_change' THEN
  credit_payload:=public.fn_accounting_credit_change_contract_v1(inv.id);
  SELECT * INTO STRICT credit_change FROM public.accounting_credit_change_documents_v1 WHERE invoice_id=inv.id;
  SELECT * INTO STRICT credit_operation FROM public.accounting_credit_reduction_operations_v1 WHERE id=credit_change.operation_receipt_id;
  users:=credit_change.audience_user_ids;sender:=credit_operation.actor_user_id;
  issuer_kind:='club';issuer_id:=credit_operation.club_id;scope_id:=credit_operation.club_id;
  issuer_name:=credit_change.issuer_name;recipient_name:=credit_change.recipient_name;
 ELSIF inv.invoice_type='accounting_correction' THEN
  SELECT * INTO correction FROM public.accounting_correction_documents WHERE invoice_id=inv.id;
  IF NOT FOUND OR correction.club_id IS DISTINCT FROM inv.club_id OR correction.source_ledger_id IS DISTINCT FROM inv.source_ledger_id
   OR correction.amount IS DISTINCT FROM inv.net_amount OR inv.breakdown IS DISTINCT FROM jsonb_build_object('category','correction','correction',public.fn_accounting_correction_payload(correction))
   OR inv.status IS DISTINCT FROM 'generated' OR inv.chips_transferred IS DISTINCT FROM false OR inv.transferred_at IS NOT NULL OR inv.due_at IS NOT NULL
  THEN RAISE EXCEPTION 'correction_document_delivery_source_unverified' USING ERRCODE='23514';END IF;
  users:=correction.audience_user_ids;sender:=correction.issuer_representative_id;
  issuer_kind:=correction.issuer_type;issuer_id:=correction.issuer_id;scope_id:=correction.club_id;
  issuer_name:=correction.issuer_name;recipient_name:=correction.payee_name;correction_payload:=public.fn_accounting_correction_payload(correction);
 ELSIF inv.invoice_type='cashier_cashout' THEN
  SELECT * INTO cashier FROM public.accounting_cashier_events WHERE invoice_id=inv.id;
  IF NOT FOUND OR cashier.club_id IS DISTINCT FROM inv.club_id OR cashier.source_ledger_id IS DISTINCT FROM inv.source_ledger_id
    OR cashier.amount IS DISTINCT FROM inv.net_amount OR inv.breakdown->'cashier' IS DISTINCT FROM public.fn_cashier_event_payload(cashier)
  THEN RAISE EXCEPTION 'cashier_delivery_event_missing' USING ERRCODE='23514';END IF;
  users:=cashier.audience_user_ids;sender:=cashier.issuer_representative_id;
  issuer_kind:='club';issuer_id:=cashier.club_id;scope_id:=cashier.club_id;
  issuer_name:=cashier.issuer_name;recipient_name:=cashier.player_name;
  cashier_payload:=public.fn_cashier_event_payload(cashier);
 ELSE
 SELECT array_agg(user_id ORDER BY user_id) INTO issuer_users FROM public.fn_accounting_invoice_party_users(inv.from_entity_type,issuer_id);
 SELECT array_agg(user_id ORDER BY user_id) INTO recipient_users FROM public.fn_accounting_invoice_party_users(inv.to_entity_type,recipient_id);
 IF COALESCE(cardinality(issuer_users),0)=0 OR COALESCE(cardinality(recipient_users),0)=0
 THEN RAISE EXCEPTION 'accounting_invoice_recipient_missing' USING ERRCODE='23514'; END IF;
 SELECT array_agg(DISTINCT x ORDER BY x) INTO users FROM unnest(issuer_users||recipient_users) x;
 -- Club senders receive one weekly summary; individual payees still get their receipt immediately.
 IF inv.from_entity_type='club' AND inv.to_entity_type IN('agent','player')
    AND inv.source_ledger_id IS NOT NULL AND inv.breakdown->>'category' IN('rakeback','commission') THEN
   users:=recipient_users;
 END IF;
 IF inv.invoice_type IN('union_weekly_squareup','union_weekly_credit_note') THEN
   issuer_kind:='union';issuer_id:=(inv.breakdown->>'union_id')::uuid;
 END IF;
 sender:=CASE WHEN issuer_kind='club' THEN (SELECT owner_id FROM public.clubs WHERE id=issuer_id)
              WHEN issuer_kind='union' THEN (SELECT owner_id FROM public.unions WHERE id=issuer_id)
              ELSE issuer_id END;
 IF sender IS NULL OR NOT sender=ANY(issuer_users||recipient_users) THEN RAISE EXCEPTION 'accounting_invoice_sender_missing' USING ERRCODE='23514'; END IF;
 issuer_name:=CASE WHEN issuer_kind='club' THEN (SELECT name FROM public.clubs WHERE id=issuer_id)
                   WHEN issuer_kind='union' THEN (SELECT name FROM public.unions WHERE id=issuer_id)
                   ELSE (SELECT username FROM public.profiles WHERE id=issuer_id) END;
 recipient_name:=CASE WHEN inv.to_entity_type='club' THEN (SELECT name FROM public.clubs WHERE id=recipient_id)
                      WHEN inv.to_entity_type='union' THEN (SELECT name FROM public.unions WHERE id=recipient_id)
                      ELSE (SELECT username FROM public.profiles WHERE id=recipient_id) END;
 END IF;
 IF inv.invoice_number IS NULL THEN
   UPDATE public.settlement_invoices SET invoice_number=public.fn_accounting_next_invoice_number() WHERE id=inv.id RETURNING invoice_number INTO inv.invoice_number;
 END IF;
 IF inv.invoice_type IN('union_weekly_squareup','union_weekly_credit_note') THEN recipient_name:=(SELECT name FROM public.clubs WHERE id=inv.club_id); END IF;
 body:=CASE WHEN inv.invoice_type='club_weekly_accounting' THEN 'Weekly Club Statement ' ELSE 'Invoice ' END||inv.invoice_number||E'\nIssued By: '||COALESCE(issuer_name,inv.from_entity_type)||E'\nFor: '||COALESCE(recipient_name,inv.to_entity_type)
  ||E'\nDirection: '||initcap(inv.from_entity_type)||' To '||initcap(inv.to_entity_type)
  ||E'\nAmount: '||to_char(abs(inv.net_amount),'FM999,999,999,999,990.00')||' Chips'
  ||E'\nStatus: '||initcap(inv.status)
  ||CASE WHEN inv.chips_transferred THEN E'\nTransfer Recorded: '||COALESCE(inv.transferred_at,inv.created_at)::text ELSE '' END
  ||CASE WHEN inv.due_at IS NOT NULL THEN E'\nDue: '||to_char(inv.due_at AT TIME ZONE 'America/Chicago','YYYY-MM-DD HH24:MI')||' Chicago Time' ELSE '' END
  ||CASE WHEN inv.breakdown ? 'period_start' THEN E'\nPeriod: '||(inv.breakdown->>'period_start')||' To '||COALESCE(inv.breakdown->>'period_end','') ELSE '' END
  ||CASE WHEN inv.notes IS NOT NULL THEN E'\n'||inv.notes ELSE '' END;
 FOR line IN SELECT key,value FROM jsonb_each_text(COALESCE(inv.breakdown,'{}'))
   WHERE key IN('rake_generated','rakeback_due','union_fee_kept','players_won','settled_in_chips','eco_amount','presettled','rake_earned','union_rake_earned','private_rake_earned','private_rake_banked','total_rake_funding','rake_received','paid_super_agents','paid_agents','paid_sub_agents','paid_players','total_paid_by_club','retained_by_club','downstream_redistributed','downstream_paid_super_agents','downstream_paid_agents','downstream_paid_sub_agents','downstream_paid_players') ORDER BY key
 LOOP
   IF line.value IS NOT NULL THEN body:=body||E'\n'||initcap(replace(line.key,'_',' '))||': '||to_char(line.value::numeric,'FM999,999,999,999,990.00'); END IF;
 END LOOP;
 IF inv.invoice_type='credit_limit_change' THEN body:=public.fn_accounting_credit_change_body_v1(credit_change.id,inv.invoice_number);
 ELSIF inv.invoice_type='cashier_cashout' THEN body:=public.fn_cashier_document_body(cashier.id,inv.invoice_number);
 ELSIF inv.invoice_type='accounting_correction' THEN body:=public.fn_accounting_correction_document_body(correction.id,inv.invoice_number);END IF;
 meta:=jsonb_build_object('kind','accounting_invoice' ,'invoice_id',inv.id,'invoice_number',inv.invoice_number,
   'club_id',inv.club_id,'source_ledger_id',inv.source_ledger_id,'source_credit_invoice_id',inv.source_credit_invoice_id,
   'source_credit_payment_id',inv.source_credit_payment_id,'amount',inv.net_amount,'currency','CHIPS','conversationId',NULL,'status',inv.status,
   'invoice_type',inv.invoice_type,'from_entity_type',inv.from_entity_type,'from_entity_id',inv.from_entity_id,
   'to_entity_type',inv.to_entity_type,'to_entity_id',inv.to_entity_id,'lines',inv.breakdown-ARRAY['source_ledger_ids','private_bank_ledger_ids','standalone_bank_ledger_ids','standalone_bank_mint_ids']);
 IF inv.invoice_type='credit_limit_change' THEN meta:=meta||jsonb_build_object('credit_change',credit_payload);
 ELSIF inv.invoice_type='cashier_cashout' THEN meta:=meta||jsonb_build_object('cashier',cashier_payload);
 ELSIF inv.invoice_type='accounting_correction' THEN meta:=meta||jsonb_build_object('correction',correction_payload);END IF;
 SELECT id INTO page_id FROM public.social_pages WHERE linked_entity_id=scope_id::text AND linked_entity_type='club' ORDER BY id LIMIT 1;
 FOREACH person IN ARRAY users LOOP
   IF EXISTS(SELECT 1 FROM public.accounting_invoice_deliveries d WHERE d.invoice_id=inv.id AND d.recipient_id=person) THEN CONTINUE; END IF;
   -- One private accounting conversation per issuer, sender, scope and recipient.
   PERFORM pg_advisory_xact_lock(hashtextextended('accounting_conversation:'||scope_id::text||':'||issuer_id::text||':'||sender::text||':'||person::text,0));
   SELECT conversation_id INTO conv FROM public.accounting_conversations c
    WHERE c.scope_id=scope_id AND c.issuer_type=issuer_kind AND c.issuer_id=issuer_id AND c.sender_id=sender AND c.recipient_id=person;
   IF conv IS NULL THEN
     INSERT INTO public.social_conversations(is_group,group_name,context_entity_id,context_entity_type)
      VALUES(true,COALESCE(issuer_name,'Account')||' Accounting',page_id,CASE WHEN page_id IS NULL THEN NULL ELSE 'club' END) RETURNING id INTO conv;
     INSERT INTO public.social_conversation_participants(conversation_id,user_id,context_entity_id,context_entity_type)
      SELECT conv,x,page_id,CASE WHEN page_id IS NULL THEN NULL ELSE 'club' END FROM (SELECT DISTINCT unnest(ARRAY[sender,person]) AS x) members;
     INSERT INTO public.accounting_conversations(scope_id,issuer_type,issuer_id,sender_id,recipient_id,conversation_id)
      VALUES(scope_id,issuer_kind,issuer_id,sender,person,conv);
   END IF;
   -- Refuse a conversation whose audience changed instead of leaking invoices.
   IF EXISTS(SELECT 1 FROM public.social_conversation_participants WHERE conversation_id=conv AND user_id<>ALL(ARRAY[sender,person]))
      OR NOT EXISTS(SELECT 1 FROM public.social_conversation_participants WHERE conversation_id=conv AND user_id=person)
      OR NOT EXISTS(SELECT 1 FROM public.social_conversation_participants WHERE conversation_id=conv AND user_id=sender)
   THEN RAISE EXCEPTION 'accounting_conversation_audience_changed' USING ERRCODE='23514'; END IF;
   meta:=meta||jsonb_build_object('conversation_id',conv,'conversationId',conv);
   INSERT INTO public.social_messages(conversation_id,sender_id,content,message_type,media_metadata)
    VALUES(conv,sender,body,'invoice',meta) RETURNING id INTO msg;
   UPDATE public.social_conversations SET last_message_at=now(),last_message_preview=left(body,100),updated_at=now() WHERE id=conv;
   meta:=meta||jsonb_build_object('conversation_id',conv,'conversationId',conv);
   INSERT INTO public.notifications(user_id,type,title,message,data,read,action_url,metadata)
    VALUES(person,CASE WHEN inv.chips_transferred AND inv.invoice_type NOT IN('credit_limit_change','accounting_correction','cashier_cashout') THEN 'accounting_invoice_detail' ELSE 'accounting_invoice' END,CASE WHEN inv.invoice_type='cashier_cashout' THEN public.fn_cashier_notice_copy(cashier,person,inv.invoice_number)->>'title' ELSE CASE WHEN inv.invoice_type='credit_limit_change' THEN 'Credit Line Updated · ' WHEN inv.invoice_type='accounting_correction' THEN 'Correction Recorded · ' WHEN inv.invoice_type='cashier_cashout' THEN CASE cashier.event_kind WHEN 'hold' THEN 'Chips Held · ' WHEN 'approval' THEN 'Cashout Approved · ' ELSE 'Chips Returned · ' END WHEN inv.invoice_type='club_weekly_accounting' THEN 'Weekly Club Statement ' ELSE 'Invoice ' END||inv.invoice_number END,
     CASE WHEN inv.invoice_type='cashier_cashout' THEN public.fn_cashier_notice_copy(cashier,person,inv.invoice_number)->>'message' ELSE CASE WHEN inv.invoice_type='credit_limit_change' THEN 'Credit capacity reduced: '||to_char(inv.net_amount,'FM999,999,999,999,990.00')||'. No payment due.'
      ELSE CASE WHEN inv.invoice_type='accounting_correction' THEN 'Correction Recorded: ' WHEN inv.invoice_type='cashier_cashout' THEN CASE cashier.event_kind WHEN 'hold' THEN 'Chips Held: ' WHEN 'approval' THEN 'Cashout Approved: ' ELSE 'Chips Returned: ' END WHEN inv.chips_transferred AND inv.breakdown->>'category'='rakeback' THEN 'Rakeback Transfer Recorded: ' WHEN inv.chips_transferred AND inv.breakdown->>'category'='commission' THEN 'Commission Transfer Recorded: ' WHEN inv.chips_transferred THEN 'Transfer Recorded: ' ELSE 'Invoice Issued: ' END||to_char(abs(inv.net_amount),'FM999,999,999,999,990.00')||' Chips' END END,
     meta,(inv.chips_transferred AND inv.invoice_type NOT IN('credit_limit_change','accounting_correction','cashier_cashout')),'/hub/messenger?conversation='||conv::text,meta) RETURNING id INTO note;
   INSERT INTO public.accounting_invoice_deliveries(invoice_id,recipient_id,message_id,notification_id) VALUES(inv.id,person,msg,note);
   count_sent:=count_sent+1;
 END LOOP;
 SELECT count(*) INTO n FROM public.accounting_invoice_deliveries WHERE invoice_id=inv.id;
 UPDATE public.settlement_invoices SET message_sent=true,message_sent_at=COALESCE(message_sent_at,now()) WHERE id=inv.id;
 RETURN jsonb_build_object('success',true,'invoice_id',inv.id,'delivered',n,'new_deliveries',count_sent);
END $function$

public.fn_deliver_club_messenger_welcome.def:
CREATE OR REPLACE FUNCTION public.fn_deliver_club_messenger_welcome()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_member record; v_admission record; v_sender uuid; v_owner uuid; v_template record; v_result jsonb;
BEGIN
 SELECT * INTO v_member FROM public.club_members WHERE club_id=NEW.club_id AND user_id=NEW.user_id;
 IF NOT FOUND OR v_member.is_active IS NOT TRUE OR v_member.status NOT IN ('active','approved') OR v_member.membership_lifecycle_status<>'active' THEN RETURN NEW; END IF;
 IF public.fn_ca_is_cert_account(NEW.user_id) THEN RETURN NEW; END IF;
 SELECT * INTO v_admission FROM public.club_messenger_admissions WHERE club_id=NEW.club_id AND user_id=NEW.user_id AND active AND transaction_id=txid_current() FOR UPDATE;
 IF NOT FOUND OR EXISTS(SELECT 1 FROM public.club_messenger_welcome_deliveries WHERE generation=v_admission.generation) THEN RETURN NEW; END IF;
 SELECT owner_id INTO v_owner FROM public.clubs WHERE id=NEW.club_id;
 v_sender:=v_member.agent_id;
 IF v_sender IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.agents WHERE club_id=NEW.club_id AND user_id=v_sender AND status='active') THEN v_sender:=NULL; END IF;
 IF v_sender IS NULL OR public.fn_club_messenger_staff_role(NEW.club_id,v_sender) IS NULL THEN v_sender:=v_owner; END IF;
 IF v_sender IS NULL OR v_sender=NEW.user_id THEN RETURN NEW; END IF;
 SELECT * INTO v_template FROM public.club_messenger_welcome_templates WHERE club_id=NEW.club_id AND user_id=v_sender AND enabled FOR SHARE;
 IF NOT FOUND THEN RETURN NEW; END IF;
 v_result:=public.fn_send_club_welcome_text(NEW.club_id,NEW.user_id,v_sender,v_template.content,v_template.revision,'downline');
 IF v_result->>'status'='cancelled' THEN RETURN NEW; END IF;
 INSERT INTO public.club_messenger_welcome_deliveries(generation,club_id,recipient_id,sender_id,template_revision,conversation_id,message_id,status)
 VALUES(v_admission.generation,NEW.club_id,NEW.user_id,v_sender,v_template.revision,(v_result->>'conversation_id')::uuid,(v_result->>'message_id')::uuid,v_result->>'status');
 IF v_result->>'status'='sent' AND v_owner<>NEW.user_id THEN
  INSERT INTO public.club_messenger_owner_followups(generation,club_id,recipient_id,sender_id,content,template_revision,due_at)
  SELECT v_admission.generation,NEW.club_id,NEW.user_id,v_owner,t.content,t.revision,clock_timestamp()+interval '10 minutes'
  FROM public.club_messenger_owner_welcome_templates t WHERE t.club_id=NEW.club_id AND t.user_id=v_owner AND t.enabled
  ON CONFLICT(generation) DO NOTHING;
 END IF;
 RETURN NEW;
END $function$

public.fn_diamond_game_reserved_cover_gu.def:
CREATE OR REPLACE FUNCTION public.fn_diamond_game_reserved_cover_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE host uuid; cover numeric; old_cover numeric; held numeric;
BEGIN
 IF TG_TABLE_NAME='clubs' THEN
  host:=NEW.id; cover:=GREATEST(COALESCE(NEW.promo_balance,0),0)+GREATEST(COALESCE(NEW.chip_treasury,0),0);
  old_cover:=GREATEST(COALESCE(OLD.promo_balance,0),0)+GREATEST(COALESCE(OLD.chip_treasury,0),0);
 ELSE
  host:=NEW.union_id; cover:=GREATEST(COALESCE(NEW.promo_wallet,0),0)+GREATEST(COALESCE(NEW.chip_balance,0),0);
  old_cover:=GREATEST(COALESCE(OLD.promo_wallet,0),0)+GREATEST(COALESCE(OLD.chip_balance,0),0);
 END IF;
 IF cover>=old_cover THEN RETURN NEW; END IF;
 SELECT COALESCE(sum(reserved_chips),0) INTO held FROM public.diamond_game_pools WHERE host_id=host;
 IF cover<held THEN RAISE EXCEPTION 'These Chips Are Reserved For Open Game Rounds'; END IF;
 RETURN NEW;
END $function$

public.fn_emit_game_management_event(p_e.def:
CREATE OR REPLACE FUNCTION public.fn_emit_game_management_event(p_event_type text, p_club_id uuid DEFAULT NULL::uuid, p_union_id uuid DEFAULT NULL::uuid, p_recipient_id uuid DEFAULT NULL::uuid, p_entity_type text DEFAULT NULL::text, p_entity_id uuid DEFAULT NULL::uuid, p_command_id uuid DEFAULT NULL::uuid, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_scope_kind text; v_scope_id uuid; v_union_id uuid;
BEGIN
  IF p_union_id IS NOT NULL THEN
    v_scope_kind := 'union'; v_scope_id := p_union_id; v_union_id := p_union_id;
  ELSIF p_club_id IS NOT NULL THEN
    SELECT s.scope_kind,s.scope_id,s.union_id
      INTO v_scope_kind,v_scope_id,v_union_id
      FROM public.fn_game_management_scope(p_club_id) s;
  END IF;
  INSERT INTO public.game_management_events(
    event_type,scope_kind,scope_id,club_id,union_id,recipient_id,
    entity_type,entity_id,command_id,actor_id,payload
  ) VALUES (
    p_event_type,v_scope_kind,v_scope_id,p_club_id,v_union_id,p_recipient_id,
    p_entity_type,p_entity_id,p_command_id,auth.uid(),COALESCE(p_payload,'{}'::jsonb)
  );
END;
$function$

public.fn_emit_management_content_event(.def:
CREATE OR REPLACE FUNCTION public.fn_emit_management_content_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_club uuid; v_union uuid; v_type text; v_id uuid; v_role text := 'host';
  v_before jsonb; v_after jsonb;
BEGIN
  IF TG_TABLE_NAME = 'game_ticker_settings' THEN
    IF TG_OP = 'UPDATE'
       AND (to_jsonb(NEW) - ARRAY['updated_at','revision'])
           IS NOT DISTINCT FROM (to_jsonb(OLD) - ARRAY['updated_at','revision']) THEN
      RETURN NULL;
    END IF;
    v_club := COALESCE(NEW.club_id, OLD.club_id);
    v_union := COALESCE(NEW.union_id, OLD.union_id);
    v_type := 'ticker_settings_changed'; v_id := COALESCE(NEW.id, OLD.id);
    v_before := CASE WHEN TG_OP='INSERT' THEN NULL ELSE jsonb_build_object('settings',OLD.settings) END;
    v_after := CASE WHEN TG_OP='DELETE' THEN NULL ELSE jsonb_build_object('settings',NEW.settings) END;
  ELSIF TG_TABLE_NAME = 'clubs' THEN
    IF NEW.tagline IS NOT DISTINCT FROM OLD.tagline
       AND NEW.lobby_message IS NOT DISTINCT FROM OLD.lobby_message
       AND NEW.description IS NOT DISTINCT FROM OLD.description THEN
      RETURN NULL;
    END IF;
    v_club := NEW.id; v_type := 'club_identity_changed'; v_id := NEW.id;
    v_before := jsonb_build_object('tagline',OLD.tagline,'lobby_message',OLD.lobby_message,'description',OLD.description);
    v_after := jsonb_build_object('tagline',NEW.tagline,'lobby_message',NEW.lobby_message,'description',NEW.description);
  ELSE
    IF TG_OP = 'UPDATE'
       AND (to_jsonb(NEW) - ARRAY['updated_at','management_revision'])
           IS NOT DISTINCT FROM (to_jsonb(OLD) - ARRAY['updated_at','management_revision']) THEN
      RETURN NULL;
    END IF;
    v_club := COALESCE(NEW.club_id,OLD.club_id);
    v_type := 'announcement_changed'; v_id := COALESCE(NEW.id,OLD.id);
    v_before := CASE WHEN TG_OP='INSERT' THEN NULL ELSE jsonb_build_object(
      'title',OLD.title,'content',OLD.content,'is_pinned',OLD.is_pinned,'is_active',OLD.is_active) END;
    v_after := CASE WHEN TG_OP='DELETE' THEN NULL ELSE jsonb_build_object(
      'title',NEW.title,'content',NEW.content,'is_pinned',NEW.is_pinned,'is_active',NEW.is_active) END;
  END IF;

  PERFORM public.fn_emit_game_management_event(
    v_type,v_club,v_union,NULL,TG_TABLE_NAME,v_id,NULL,
    jsonb_build_object('operation',lower(TG_OP)));

  IF auth.uid() IS NOT NULL THEN
    IF v_union IS NOT NULL OR EXISTS (
      SELECT 1 FROM public.union_clubs WHERE club_id=v_club) THEN
      v_role := 'union_admin';
    ELSE
      SELECT CASE WHEN c.owner_id=auth.uid() THEN 'owner'
                  WHEN m.role='co_owner' THEN 'co_owner'
                  WHEN m.role='admin' THEN 'admin' ELSE 'host' END
        INTO v_role FROM public.clubs c
        LEFT JOIN public.club_members m
          ON m.club_id=c.id AND m.user_id=auth.uid()
       WHERE c.id=v_club;
    END IF;
    INSERT INTO public.audit_trail(
      actor_id,actor_role,action,target_type,target_id,club_id,before_state,after_state
    ) VALUES (
      auth.uid(),COALESCE(v_role,'host'),v_type,TG_TABLE_NAME,v_id,v_club,v_before,v_after);
  END IF;
  RETURN NULL;
END;
$function$

public.fn_enforce_four_club_limit().def:
CREATE OR REPLACE FUNCTION public.fn_enforce_four_club_limit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_count int;
BEGIN
  IF NEW.status NOT IN ('active', 'approved') THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND OLD.status IN ('active', 'approved') THEN
    RETURN NEW;
  END IF;

  -- THE UNION OWNER IS A MEMBER OF EVERY CLUB (2026-10-12): the membership
  -- the union rule makes is the platform's, not a club the owner chose, so the
  -- personal club cap does not refuse it (fn_union_owner_holds_membership).
  IF COALESCE(current_setting('app.club_membership_source', true), '') = 'union_owner_membership' THEN
    RETURN NEW;
  END IF;

  IF EXISTS (
    SELECT 1 FROM profiles WHERE id = NEW.user_id AND COALESCE(is_horse, false)
  ) THEN
    RETURN NEW;
  END IF;

  PERFORM public.fn_club_membership_lock(NEW.user_id);
  v_count := public.fn_club_membership_count(NEW.user_id, NEW.club_id);

  IF v_count >= public.fn_club_membership_cap() THEN
    RAISE EXCEPTION
      'You can only be a member of up to % clubs. Leave a club to join a new one.',
      public.fn_club_membership_cap()
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$function$

public.fn_guard_agent_agreement().def:
CREATE OR REPLACE FUNCTION public.fn_guard_agent_agreement()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE parent public.agents%ROWTYPE;child record;field text;new_value numeric;old_value numeric;parent_value numeric;child_value numeric;
 old_terms jsonb;new_terms jsonb;parent_terms jsonb;new_edge boolean;
BEGIN
 IF TG_OP='UPDATE' AND (NEW.id IS DISTINCT FROM OLD.id OR NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.club_id IS DISTINCT FROM OLD.club_id) THEN
  RAISE EXCEPTION 'agent financial account identity is immutable; create a separate account for another club or user' USING ERRCODE='23514';END IF;
 -- All agreement RPCs take this same club lock before reading terms. Direct
 -- writes also pass this guard; the financial account's club is immutable.
 PERFORM pg_advisory_xact_lock(hashtextextended('agent-agreement:'||NEW.club_id::text,0));
 old_terms:=CASE WHEN TG_OP='UPDATE' THEN to_jsonb(OLD) ELSE '{}'::jsonb END;
 new_terms:=to_jsonb(NEW);
 new_edge:=TG_OP='INSERT' OR NEW.parent_agent_id IS DISTINCT FROM OLD.parent_agent_id OR NEW.club_id IS DISTINCT FROM OLD.club_id;
 IF NEW.parent_agent_id IS NOT NULL THEN
  SELECT * INTO parent FROM public.agents WHERE id=NEW.parent_agent_id AND club_id=NEW.club_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'parent agent must belong to the same club' USING ERRCODE='23514';END IF;
  IF NEW.parent_agent_id=NEW.id OR EXISTS(WITH RECURSIVE chain AS (
    SELECT id,parent_agent_id FROM public.agents WHERE id=NEW.parent_agent_id AND club_id=NEW.club_id
    UNION SELECT a.id,a.parent_agent_id FROM public.agents a JOIN chain c ON a.id=c.parent_agent_id WHERE a.club_id=NEW.club_id
   ) SELECT 1 FROM chain WHERE id=NEW.id) THEN
   RAISE EXCEPTION 'agent hierarchy cannot contain a cycle' USING ERRCODE='23514';END IF;
  IF new_edge AND (parent.role='sub_agent' OR parent.status IS DISTINCT FROM 'active') THEN
   RAISE EXCEPTION 'new parent must be an active agent or super agent' USING ERRCODE='23514';END IF;
  parent_terms:=to_jsonb(parent);
 END IF;
 IF NEW.role='sub_agent' AND (TG_OP='INSERT' OR NEW.role IS DISTINCT FROM OLD.role)
  AND EXISTS(SELECT 1 FROM public.agents c WHERE c.parent_agent_id=NEW.id) THEN
  RAISE EXCEPTION 'a sub-agent cannot have agent children' USING ERRCODE='23514';END IF;

 FOREACH field IN ARRAY ARRAY['commission_rate','player_rakeback_rate','credit_limit'] LOOP
  new_value:=(new_terms->>field)::numeric;old_value:=(old_terms->>field)::numeric;
  IF TG_OP='INSERT' OR new_value IS DISTINCT FROM old_value THEN
   IF new_value IS NULL OR new_value::text IN('NaN','Infinity','-Infinity') OR new_value<0
    OR (field='credit_limit' AND new_value<>round(new_value,2))
    OR (field='commission_rate' AND new_value>0.70)
    OR (field='player_rakeback_rate' AND new_value>0.50) THEN
    RAISE EXCEPTION 'invalid agent agreement value: %',field USING ERRCODE='23514';END IF;
  END IF;
  IF field='player_rakeback_rate' AND (TG_OP='INSERT' OR new_value IS DISTINCT FROM old_value)
     AND new_value > COALESCE((new_terms->>'commission_rate')::numeric, 0) THEN
   RAISE EXCEPTION 'agent player_rakeback_rate cannot exceed its own commission_rate' USING ERRCODE='23514';END IF;
  IF field<>'player_rakeback_rate' AND NEW.parent_agent_id IS NOT NULL AND (new_edge OR new_value IS DISTINCT FROM old_value) THEN
   parent_value:=(parent_terms->>field)::numeric;
   IF parent_value IS NOT NULL AND greatest(new_value-parent_value,0)>
      (CASE WHEN new_edge THEN 0 ELSE greatest(old_value-parent_value,0) END) THEN
    RAISE EXCEPTION 'agent % cannot exceed or worsen its parent cap',field USING ERRCODE='23514';END IF;
  END IF;
  IF TG_OP='UPDATE' AND field<>'player_rakeback_rate' AND new_value IS DISTINCT FROM old_value THEN
   FOR child IN SELECT to_jsonb(a) AS terms FROM public.agents a WHERE a.parent_agent_id=NEW.id AND a.club_id=NEW.club_id LOOP
    child_value:=(child.terms->>field)::numeric;
    IF child_value IS NOT NULL AND greatest(child_value-new_value,0)>greatest(child_value-old_value,0) THEN
     RAISE EXCEPTION 'agent % cannot be reduced below an existing child agreement',field USING ERRCODE='23514';END IF;
   END LOOP;
  END IF;
 END LOOP;
 RETURN NEW;
END $function$

public.fn_guard_club_lifecycle_write().def:
CREATE OR REPLACE FUNCTION public.fn_guard_club_lifecycle_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_retirement_write boolean :=
    coalesce(current_setting('app.club_retirement_write', true), '') = 'on';
  v_maintenance boolean :=
    auth.uid() IS NULL
    AND coalesce(current_setting('app.club_retirement_maintenance', true), '') = 'on';
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF NOT v_maintenance AND NOT (
      auth.uid() IS NULL
      AND (OLD.name LIKE 'Crest Cert %' OR OLD.name LIKE 'Preset Crest Cert %')
      AND coalesce(current_setting('app.ledger_maintenance', true), '') <> ''
      AND coalesce(current_setting('app.game_management_retention', true), '') = 'on'
    ) THEN
      RAISE EXCEPTION 'CLUB_RECORD_RETAINED: real club records cannot be deleted'
        USING ERRCODE = '55000';
    END IF;
    RETURN OLD;
  END IF;

  IF OLD.lifecycle_status = 'retired' AND NOT v_maintenance THEN
    RAISE EXCEPTION 'CLUB_RETIRED: this club is read-only'
      USING ERRCODE = '55000';
  END IF;

  IF (NEW.lifecycle_status, NEW.retired_at, NEW.retired_by, NEW.retirement_reason)
       IS DISTINCT FROM
     (OLD.lifecycle_status, OLD.retired_at, OLD.retired_by, OLD.retirement_reason)
     AND NOT v_retirement_write
     AND NOT v_maintenance THEN
    RAISE EXCEPTION 'CLUB_LIFECYCLE_REQUIRES_RPC: use fn_retire_settled_club'
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END
$function$

public.fn_guard_retired_club_mutation().def:
CREATE OR REPLACE FUNCTION public.fn_guard_retired_club_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_club_id uuid;
  v_old_club_id uuid;
  v_maintenance boolean :=
    auth.uid() IS NULL
    AND coalesce(current_setting('app.club_retirement_maintenance', true), '') = 'on';
BEGIN
  IF v_maintenance THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'DELETE' THEN
    IF TG_TABLE_NAME = 'unions' THEN
      v_club_id := OLD.id;
    ELSIF TG_TABLE_NAME = 'table_seats' THEN
      SELECT t.club_id INTO v_club_id FROM public.tables t WHERE t.id = OLD.table_id;
    ELSIF TG_TABLE_NAME IN ('tournament_players', 'tournament_escrow') THEN
      SELECT t.club_id INTO v_club_id FROM public.tournaments t WHERE t.id = OLD.tournament_id;
    ELSIF TG_TABLE_NAME = 'chip_escrow' THEN
      SELECT cr.club_id INTO v_club_id FROM public.cashout_requests cr WHERE cr.id = OLD.cashout_request_id;
    ELSIF TG_TABLE_NAME = 'credit_invoices' THEN
      SELECT a.club_id INTO v_club_id FROM public.agents a WHERE a.id = OLD.agent_id;
    ELSIF TG_TABLE_NAME = 'tournament_schedule_spawns' THEN
      SELECT s.club_id INTO v_club_id FROM public.tournament_schedules s WHERE s.id = OLD.schedule_id;
    ELSIF TG_TABLE_NAME = 'managed_game_schedules' THEN
      IF OLD.game_kind = 'table' THEN
        SELECT t.club_id INTO v_club_id FROM public.tables t WHERE t.id = OLD.game_id;
      ELSE
        SELECT t.club_id INTO v_club_id FROM public.tournaments t WHERE t.id = OLD.game_id;
      END IF;
    ELSIF TG_TABLE_NAME IN ('wheel_configs','diamond_game_configs') THEN
      IF OLD.host_kind = 'club' THEN v_club_id := OLD.host_id; END IF;
    ELSIF TG_TABLE_NAME = 'wheel_pools' THEN
      SELECT c.host_id INTO v_club_id FROM public.wheel_configs c
       WHERE c.host_id=OLD.host_id AND c.host_kind='club';
    ELSIF TG_TABLE_NAME = 'diamond_game_pools' THEN
      SELECT c.host_id INTO v_club_id FROM public.diamond_game_configs c
       WHERE c.host_id=OLD.host_id AND c.game=OLD.game AND c.host_kind='club';
    ELSE
      v_club_id := OLD.club_id;
    END IF;
  ELSE
    IF TG_TABLE_NAME = 'unions' THEN
      v_club_id := NEW.id;
    ELSIF TG_TABLE_NAME = 'table_seats' THEN
      SELECT t.club_id INTO v_club_id FROM public.tables t WHERE t.id = NEW.table_id;
    ELSIF TG_TABLE_NAME IN ('tournament_players', 'tournament_escrow') THEN
      SELECT t.club_id INTO v_club_id FROM public.tournaments t WHERE t.id = NEW.tournament_id;
    ELSIF TG_TABLE_NAME = 'chip_escrow' THEN
      SELECT cr.club_id INTO v_club_id FROM public.cashout_requests cr WHERE cr.id = NEW.cashout_request_id;
    ELSIF TG_TABLE_NAME = 'credit_invoices' THEN
      SELECT a.club_id INTO v_club_id FROM public.agents a WHERE a.id = NEW.agent_id;
    ELSIF TG_TABLE_NAME = 'tournament_schedule_spawns' THEN
      SELECT s.club_id INTO v_club_id FROM public.tournament_schedules s WHERE s.id = NEW.schedule_id;
    ELSIF TG_TABLE_NAME = 'managed_game_schedules' THEN
      IF NEW.game_kind = 'table' THEN
        SELECT t.club_id INTO v_club_id FROM public.tables t WHERE t.id = NEW.game_id;
      ELSE
        SELECT t.club_id INTO v_club_id FROM public.tournaments t WHERE t.id = NEW.game_id;
      END IF;
    ELSIF TG_TABLE_NAME IN ('wheel_configs','diamond_game_configs') THEN
      IF NEW.host_kind = 'club' THEN v_club_id := NEW.host_id; END IF;
    ELSIF TG_TABLE_NAME = 'wheel_pools' THEN
      SELECT c.host_id INTO v_club_id FROM public.wheel_configs c
       WHERE c.host_id=NEW.host_id AND c.host_kind='club';
    ELSIF TG_TABLE_NAME = 'diamond_game_pools' THEN
      SELECT c.host_id INTO v_club_id FROM public.diamond_game_configs c
       WHERE c.host_id=NEW.host_id AND c.game=NEW.game AND c.host_kind='club';
    ELSE
      v_club_id := NEW.club_id;
    END IF;

    IF TG_OP = 'UPDATE' THEN
      IF TG_TABLE_NAME = 'unions' THEN
        v_old_club_id := OLD.id;
      ELSIF TG_TABLE_NAME = 'table_seats' THEN
        SELECT t.club_id INTO v_old_club_id FROM public.tables t WHERE t.id = OLD.table_id;
      ELSIF TG_TABLE_NAME IN ('tournament_players', 'tournament_escrow') THEN
        SELECT t.club_id INTO v_old_club_id FROM public.tournaments t WHERE t.id = OLD.tournament_id;
      ELSIF TG_TABLE_NAME = 'chip_escrow' THEN
        SELECT cr.club_id INTO v_old_club_id FROM public.cashout_requests cr WHERE cr.id = OLD.cashout_request_id;
      ELSIF TG_TABLE_NAME = 'credit_invoices' THEN
        SELECT a.club_id INTO v_old_club_id FROM public.agents a WHERE a.id = OLD.agent_id;
      ELSIF TG_TABLE_NAME = 'tournament_schedule_spawns' THEN
        SELECT s.club_id INTO v_old_club_id FROM public.tournament_schedules s WHERE s.id = OLD.schedule_id;
      ELSIF TG_TABLE_NAME = 'managed_game_schedules' THEN
        IF OLD.game_kind = 'table' THEN
          SELECT t.club_id INTO v_old_club_id FROM public.tables t WHERE t.id = OLD.game_id;
        ELSE
          SELECT t.club_id INTO v_old_club_id FROM public.tournaments t WHERE t.id = OLD.game_id;
        END IF;
      ELSIF TG_TABLE_NAME IN ('wheel_configs','diamond_game_configs') THEN
        IF OLD.host_kind = 'club' THEN v_old_club_id := OLD.host_id; END IF;
      ELSIF TG_TABLE_NAME = 'wheel_pools' THEN
        SELECT c.host_id INTO v_old_club_id FROM public.wheel_configs c
         WHERE c.host_id=OLD.host_id AND c.host_kind='club';
      ELSIF TG_TABLE_NAME = 'diamond_game_pools' THEN
        SELECT c.host_id INTO v_old_club_id FROM public.diamond_game_configs c
         WHERE c.host_id=OLD.host_id AND c.game=OLD.game AND c.host_kind='club';
      ELSE
        v_old_club_id := OLD.club_id;
      END IF;
    END IF;
  END IF;

  IF TG_TABLE_NAME = 'unions' AND v_club_id IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('cashier-hierarchy:' || v_club_id::text, 0));
  END IF;

  -- Lock both scopes in UUID order.  A writer that began just before retirement
  -- waits here and then observes the committed retired lifecycle.
  PERFORM 1
    FROM public.clubs c
   WHERE c.id IN (v_club_id, v_old_club_id)
   ORDER BY c.id
   FOR KEY SHARE;

  -- These two owning stores have no club FK. Recheck after the shared
  -- parent lock: cleanup may have deleted that parent while this writer waited.
  IF TG_OP <> 'DELETE' AND TG_TABLE_NAME IN ('cash_games','tournament_schedules')
     AND v_club_id IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM public.clubs WHERE id=v_club_id) THEN
    RAISE EXCEPTION 'CLUB_NOT_FOUND: game records require their owning club'
      USING ERRCODE='23503';
  END IF;

  IF (v_club_id IS NOT NULL OR v_old_club_id IS NOT NULL) AND EXISTS (
    SELECT 1 FROM public.clubs c
     WHERE c.id IN (v_club_id, v_old_club_id) AND c.lifecycle_status = 'retired'
  ) THEN
    RAISE EXCEPTION 'CLUB_RETIRED: gameplay and cashier records are read-only'
      USING ERRCODE = '55000';
  END IF;

  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END
$function$

public.fn_invoice_accounting_ledger_tran.def:
CREATE OR REPLACE FUNCTION public.fn_invoice_accounting_ledger_transfer(p_ledger_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE leg public.chip_ledger%ROWTYPE; inv_id uuid; issuer_kind text; issuer_id uuid; payee_kind text; payee_id uuid; kind text; recorded_role text; routed boolean; correction public.accounting_correction_documents%ROWTYPE;
BEGIN
 SELECT * INTO leg FROM public.chip_ledger WHERE id=p_ledger_id;
 IF leg.metadata->>'entry_kind'='launch_closing_position' THEN RETURN NULL; END IF;
 IF public.fn_ca_launch_is_internal_transfer(leg.id) THEN RETURN NULL; END IF;
 IF NOT FOUND OR leg.status IS DISTINCT FROM 'posted' OR leg.amount IS NULL OR leg.amount<=0
    OR leg.amount::text IN('NaN','Infinity','-Infinity') OR leg.amount<>round(leg.amount,2)
 THEN RAISE EXCEPTION 'invalid_accounting_transfer' USING ERRCODE='23514'; END IF;
 IF leg.category='correction' THEN
  PERFORM pg_advisory_xact_lock(hashtextextended('accounting_ledger_invoice:'||leg.id::text,0));
  SELECT * INTO correction FROM public.accounting_correction_documents WHERE source_ledger_id=leg.id;
  IF NOT FOUND THEN RAISE EXCEPTION 'historical_correction_document_unverified' USING ERRCODE='23514';END IF;
  SELECT id INTO inv_id FROM public.settlement_invoices WHERE source_ledger_id=leg.id;
  IF inv_id IS NOT NULL THEN
   IF inv_id IS DISTINCT FROM correction.invoice_id THEN RAISE EXCEPTION 'correction_document_invoice_collision' USING ERRCODE='23514';END IF;
   PERFORM public.fn_accounting_correction_assert_delivery(correction.id);
   RETURN inv_id;
  END IF;
  INSERT INTO public.settlement_invoices(id,club_id,invoice_type,from_entity_type,from_entity_id,to_entity_type,to_entity_id,
    gross_amount,net_amount,deductions,breakdown,status,chips_transferred,transferred_at,due_at,notes,source_ledger_id,created_at)
  VALUES(correction.invoice_id,correction.club_id,'accounting_correction',correction.issuer_type,correction.issuer_id::text,
    correction.payee_type,correction.payee_id::text,correction.amount,correction.amount,0,
    jsonb_build_object('category','correction','correction',public.fn_accounting_correction_payload(correction)),
    'generated',false,NULL,NULL,NULL,leg.id,correction.issued_at) RETURNING id INTO inv_id;
  IF NOT FOUND OR inv_id IS DISTINCT FROM correction.invoice_id THEN RAISE EXCEPTION 'correction_document_invoice_write_missing' USING ERRCODE='23514';END IF;
  PERFORM public.fn_deliver_accounting_invoice(inv_id);
  PERFORM public.fn_accounting_correction_assert_delivery(correction.id);
  RETURN inv_id;
 END IF;
 routed:=COALESCE(leg.metadata->>'routing_version'='3'
  AND current_setting('app.accounting_routing_context',true)=
   CASE WHEN leg.union_id IS NOT NULL THEN leg.union_id::text
    WHEN leg.metadata->>'accounting_scope_kind'='club' AND leg.metadata->>'accounting_scope_id'=leg.club_id::text
     THEN 'club:'||leg.club_id::text END
   ||':'||((leg.metadata->>'period_start')::timestamptz)::text||':'||((leg.metadata->>'period_end')::timestamptz)::text,false);
 recorded_role:=CASE WHEN routed THEN leg.metadata->>'payee_role_at_transfer' END;
 IF routed AND leg.to_type IN('player_wallet','agent_wallet') AND (recorded_role IS NULL OR recorded_role NOT IN('player','sub_agent','agent','super_agent')) THEN
  RAISE EXCEPTION 'routed_payment_recipient_role_missing' USING ERRCODE='23514'; END IF;

 IF leg.from_type IN('union_wallet','union_bank') THEN issuer_kind:='union';issuer_id:=leg.from_entity_id;
 ELSIF leg.from_type='club_treasury' THEN issuer_kind:='club';issuer_id:=leg.from_entity_id;
 ELSIF leg.from_type IN('player_wallet','agent_wallet') THEN issuer_id:=leg.from_entity_id;
   issuer_kind:=CASE WHEN routed OR leg.from_type='agent_wallet' OR EXISTS(SELECT 1 FROM public.agents a WHERE a.user_id=issuer_id AND a.club_id=leg.club_id) THEN 'agent' ELSE 'player' END;
 ELSIF leg.from_type='settlement_suspense' AND leg.category='rakeback' AND leg.club_id IS NOT NULL THEN
   -- Club-issued receipt for the existing clearing-account leg; preserve its actual source in breakdown.
   issuer_kind:='club';issuer_id:=leg.club_id;
 ELSE RAISE EXCEPTION 'unsupported_accounting_transfer_source' USING ERRCODE='23514'; END IF;
 -- Game payout journals retain the physical union_wallets.id store identity.
 -- Accounting parties use unions.id. Resolve only a matching, declared host;
 -- never rewrite the original journal or infer a different union.
 IF leg.category IN('wheel_prize','plinko_prize','crash_prize','crossing_prize','mines_prize')
    AND issuer_kind='union' AND leg.union_id IS NOT NULL
    AND EXISTS(SELECT 1 FROM public.union_wallets w WHERE w.id=issuer_id AND w.union_id=leg.union_id)
 THEN issuer_id:=leg.union_id; END IF;
 IF leg.to_type IN('union_wallet','union_bank') THEN payee_kind:='union';payee_id:=leg.to_entity_id;
 ELSIF leg.to_type='club_treasury' THEN payee_kind:='club';payee_id:=leg.to_entity_id;
 ELSIF leg.to_type IN('player_wallet','agent_wallet') THEN
   payee_id:=leg.to_entity_id;
   payee_kind:=CASE WHEN routed THEN CASE WHEN recorded_role='player' THEN 'player' ELSE 'agent' END WHEN leg.category='commission' OR EXISTS(SELECT 1 FROM public.agents a WHERE a.user_id=payee_id AND a.club_id=leg.club_id) THEN 'agent' ELSE 'player' END;
 ELSE RAISE EXCEPTION 'unsupported_accounting_transfer_recipient' USING ERRCODE='23514'; END IF;
 kind:=CASE WHEN issuer_kind='union' AND payee_kind='club' THEN 'union_to_club'
            WHEN issuer_kind='club' AND payee_kind='agent' THEN 'club_to_agent'
            WHEN issuer_kind='agent' AND payee_kind='agent' THEN 'agent_to_subagent'
            WHEN issuer_kind='agent' AND payee_kind='player' THEN 'agent_to_player' ELSE 'transaction_receipt' END;
 PERFORM pg_advisory_xact_lock(hashtextextended('accounting_ledger_invoice:'||leg.id::text,0));
 SELECT id INTO inv_id FROM public.settlement_invoices WHERE source_ledger_id=leg.id;
 IF inv_id IS NULL THEN
   INSERT INTO public.settlement_invoices(club_id,invoice_type,from_entity_type,from_entity_id,to_entity_type,to_entity_id,
    gross_amount,net_amount,deductions,breakdown,status,chips_transferred,transferred_at,notes,source_ledger_id)
   VALUES(COALESCE(leg.club_id,leg.union_id),kind,issuer_kind,issuer_id::text,payee_kind,payee_id::text,leg.amount,leg.amount,0,
    COALESCE(leg.metadata,'{}'::jsonb)||jsonb_build_object('ledger_id',leg.id,'category',leg.category,'ledger_from_type',leg.from_type,
      'ledger_from_entity_id',leg.from_entity_id,'ledger_to_type',leg.to_type,'ledger_to_entity_id',leg.to_entity_id,
      'payee_role_at_transfer',CASE WHEN routed AND recorded_role IS NOT NULL THEN recorded_role WHEN payee_kind='player' THEN 'player' ELSE (SELECT a.role FROM public.agents a WHERE a.user_id=payee_id AND a.club_id=leg.club_id ORDER BY a.id LIMIT 1) END),
    'paid',true,leg.created_at,'Receipt For A Posted Accounting Transfer. This Does Not Certify The Entire Weekly Close.',leg.id)
   RETURNING id INTO inv_id;
 END IF;
 PERFORM public.fn_deliver_accounting_invoice(inv_id);
 RETURN inv_id;
END $function$

public.fn_is_platform_admin().def:
CREATE OR REPLACE FUNCTION public.fn_is_platform_admin()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_role text;
BEGIN
  IF auth.uid() IS NULL THEN RETURN false; END IF;
  SELECT role INTO v_role FROM public.profiles WHERE id = auth.uid();
  -- No profile row, or a NULL role, is not staff: never NULL (#9390).
  RETURN COALESCE(v_role IN ('admin', 'superadmin', 'god'), false);
END;
$function$

public.fn_member_rakeback_explicit_guard.def:
CREATE OR REPLACE FUNCTION public.fn_member_rakeback_explicit_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE changed boolean;
BEGIN
 IF TG_OP='INSERT' THEN
  changed:=coalesce(NEW.player_rakeback_pct,0)<>0 OR NEW.player_rakeback_explicit;
 ELSE
  changed:=NEW.player_rakeback_pct IS DISTINCT FROM OLD.player_rakeback_pct
    OR NEW.player_rakeback_explicit IS DISTINCT FROM OLD.player_rakeback_explicit;
 END IF;
 IF changed AND current_user NOT IN ('postgres','supabase_admin','service_role') THEN
  RAISE EXCEPTION 'Individual Rakeback Must Be Set Through Its Agreement RPC' USING ERRCODE='42501';
 END IF;
 RETURN NEW;
END $function$

public.fn_membership_approval_gate().def:
CREATE OR REPLACE FUNCTION public.fn_membership_approval_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid;
  v_requires boolean;
  v_owner uuid;
BEGIN
  IF NEW.status NOT IN ('active', 'approved') THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.status IN ('active', 'approved') THEN
    RETURN NEW;
  END IF;

  IF current_user NOT IN ('authenticated', 'anon') THEN
    RETURN NEW;
  END IF;

  v_uid := auth.uid();

  IF NEW.user_id IS DISTINCT FROM v_uid THEN
    RETURN NEW;
  END IF;

  SELECT COALESCE(requires_approval, false), owner_id
    INTO v_requires, v_owner
    FROM clubs WHERE id = NEW.club_id;

  IF NOT FOUND OR NOT v_requires THEN
    RETURN NEW;
  END IF;

  IF v_owner = v_uid OR is_club_admin(NEW.club_id, v_uid) THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    NEW.status := 'pending';
    RETURN NEW;
  END IF;

  RAISE EXCEPTION
    'This club requires owner approval. Your request is pending review.'
    USING ERRCODE = 'check_violation';
END;
$function$

public.fn_midway_cash_rake_write_guard().def:
CREATE OR REPLACE FUNCTION public.fn_midway_cash_rake_write_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_union uuid; v_asset text;
BEGIN
  IF TG_TABLE_NAME='clubs' THEN
    IF NEW.asset='diamonds' THEN RETURN NEW; END IF;
    IF NEW.union_id='fade0000-0000-0000-0000-000000000001'::uuid
       OR NEW.id='fade0000-0000-0000-0000-000000000001'::uuid THEN
      NEW.rake_cap := CASE WHEN NEW.rake_cap > 2.5 THEN 2.5 ELSE NEW.rake_cap END;
      IF NEW.default_rake_percent > 10 THEN
        RAISE EXCEPTION 'Midway Cash Rake Is Limited To 10 Percent And 2.5 BB';
      END IF;
    END IF;
  ELSE
    IF NEW.tournament_id IS NOT NULL THEN RETURN NEW; END IF;
    SELECT c.union_id,c.asset INTO v_union,v_asset FROM public.clubs c WHERE c.id=NEW.club_id;
    IF v_asset='diamonds' THEN RETURN NEW; END IF;
    IF NEW.union_id='fade0000-0000-0000-0000-000000000001'::uuid
       OR v_union='fade0000-0000-0000-0000-000000000001'::uuid THEN
      NEW.rake_cap_bb := CASE WHEN NEW.rake_cap_bb > 2.5 THEN 2.5 ELSE NEW.rake_cap_bb END;
      IF NEW.rake_percent > 10 THEN
        RAISE EXCEPTION 'Midway Cash Rake Is Limited To 10 Percent And 2.5 BB';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END $function$

public.fn_poker_guard_arena_structure().def:
CREATE OR REPLACE FUNCTION public.fn_poker_guard_arena_structure()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_asset text;
BEGIN
  IF TG_TABLE_NAME='clubs' THEN
    IF TG_OP='UPDATE' AND (NEW.asset,NEW.is_platform) IS DISTINCT FROM (OLD.asset,OLD.is_platform) THEN
      RAISE EXCEPTION 'Arena Asset Is Immutable' USING ERRCODE='23514';
    END IF;
    IF NEW.asset='diamonds' AND auth.uid() IS NOT NULL AND coalesce(auth.jwt()->>'role','') <> 'service_role'
       AND NOT coalesce(public.fn_is_platform_admin(),false) THEN
      RAISE EXCEPTION 'Diamond Arena Requires Platform Operations' USING ERRCODE='42501';
    END IF;
    -- THE ARENA BELONGS TO THE SYSTEM (2026-09-30, decided by Claude on Dan's
    -- delegation): a Diamond club is owned by the system account, which nobody
    -- signs in as, so no door that trusts a club's owner admits a person to
    -- the arena. Platform staff run it through the staff doors.
    IF NEW.asset='diamonds' AND NEW.owner_id IS DISTINCT FROM '00000000-0000-0000-0000-000000000001'::uuid THEN
      RAISE EXCEPTION 'The Diamond Arena Belongs To The System' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
  END IF;
  SELECT asset INTO v_asset FROM public.clubs WHERE id=NEW.club_id;
  IF TG_TABLE_NAME='club_members' AND TG_OP='UPDATE' AND NEW.club_id IS DISTINCT FROM OLD.club_id
     AND EXISTS (SELECT 1 FROM public.clubs WHERE id=OLD.club_id AND asset='diamonds') THEN
    RAISE EXCEPTION 'Diamond Participation Cannot Become A Chip Membership' USING ERRCODE='23514';
  END IF;
  -- Branch before resolving fields: membership rows do not have union_id.
  IF TG_TABLE_NAME IN ('tables','tournaments') THEN
    IF TG_OP='UPDATE' AND NEW.club_id IS DISTINCT FROM OLD.club_id
       AND (EXISTS (SELECT 1 FROM public.clubs WHERE id=OLD.club_id AND asset IS DISTINCT FROM v_asset)
         OR (OLD.club_id IS NULL AND OLD.union_id IS NOT NULL AND v_asset='diamonds')) THEN
      RAISE EXCEPTION 'Game Asset Is Immutable' USING ERRCODE='23514';
    END IF;
  END IF;
  IF v_asset='diamonds' THEN
    IF TG_TABLE_NAME='club_members' THEN
      IF TG_OP='INSERT' OR NEW.role IS DISTINCT FROM 'player' OR NEW.status IS DISTINCT FROM 'automatic'
         OR NEW.agent_id IS NOT NULL OR NEW.parent_agent_id IS NOT NULL
         OR coalesce(NEW.chip_balance,0)<>0 OR coalesce(NEW.credit_limit,0)<>0
         OR coalesce(NEW.credit_used,0)<>0 OR coalesce(NEW.promo_balance,0)<>0
         OR coalesce(NEW.held_chips,0)<>0 THEN
        RAISE EXCEPTION 'Diamond Membership Is Automatic And Has No Chip Wallet Or Hierarchy' USING ERRCODE='23514';
      END IF;
    ELSIF TG_TABLE_NAME='union_clubs' THEN
      RAISE EXCEPTION 'Diamond Arena Cannot Join A Union' USING ERRCODE='23514';
    ELSIF auth.uid() IS NOT NULL AND coalesce(auth.jwt()->>'role','') <> 'service_role'
       AND NOT coalesce(public.fn_is_platform_admin(),false)
       -- DIAMOND PHASE 8: a player's entry, add-on and withdrawal move the
       -- play-state counters through the estate's doors; the structure is
       -- still platform operations only.
       AND NOT (TG_OP='UPDATE' AND TG_TABLE_NAME IN ('tournaments','tables')
                -- DIAMOND PHASE 11: a stored generated column is NULL in NEW before
                -- the row is written, and follows the base columns compared here; it
                -- is left out, or a player's buy-in reads as a structural change.
                AND (to_jsonb(NEW) - public.fn_poker_diamond_play_state_columns(TG_TABLE_NAME)
                       - ARRAY(SELECT a.attname::text FROM pg_catalog.pg_attribute a
                                WHERE a.attrelid = TG_RELID AND a.attgenerated <> '' AND NOT a.attisdropped))
                  = (to_jsonb(OLD) - public.fn_poker_diamond_play_state_columns(TG_TABLE_NAME)
                       - ARRAY(SELECT a.attname::text FROM pg_catalog.pg_attribute a
                                WHERE a.attrelid = TG_RELID AND a.attgenerated <> '' AND NOT a.attisdropped))) THEN
      RAISE EXCEPTION 'Diamond Games Require Platform Operations' USING ERRCODE='42501';
    ELSIF NEW.union_id IS NOT NULL THEN
      RAISE EXCEPTION 'Diamond Games Cannot Belong To A Union' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NEW;
END $function$

public.fn_publish_agent_wallet_change().def:
CREATE OR REPLACE FUNCTION public.fn_publish_agent_wallet_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF TG_OP = 'UPDATE' AND
    ROW(OLD.club_id, OLD.user_id, OLD.status, OLD.agent_wallet_balance, OLD.promo_wallet_balance)
    IS NOT DISTINCT FROM
    ROW(NEW.club_id, NEW.user_id, NEW.status, NEW.agent_wallet_balance, NEW.promo_wallet_balance)
  THEN RETURN NEW; END IF;
  -- Transport failure cannot roll back an authoritative financial transaction.
  -- Rejoin/visibility re-reads recover persisted balances, with no repair loop.
  BEGIN
    IF TG_OP <> 'INSERT' THEN
      PERFORM realtime.send(jsonb_build_object('club_id', OLD.club_id, 'user_id', OLD.user_id),
        'wallet_changed', 'club-roster-wallet:' || OLD.club_id::text, true);
    END IF;
    IF TG_OP = 'INSERT' OR (TG_OP = 'UPDATE' AND
      ROW(OLD.club_id, OLD.user_id) IS DISTINCT FROM ROW(NEW.club_id, NEW.user_id)) THEN
      PERFORM realtime.send(jsonb_build_object('club_id', NEW.club_id, 'user_id', NEW.user_id),
        'wallet_changed', 'club-roster-wallet:' || NEW.club_id::text, true);
    END IF;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'Agent wallet signal delivery failed: %', SQLERRM;
  END;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$

public.fn_publish_club_roster(p_club uui.def:
CREATE OR REPLACE FUNCTION public.fn_publish_club_roster(p_club uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE target uuid; sent jsonb:=coalesce(nullif(current_setting('ca.roster_signaled_clubs',true),''),'[]')::jsonb;
BEGIN
 IF p_club IS NULL THEN RETURN; END IF;
 FOR target IN
   SELECT p_club
   UNION SELECT c.union_id FROM public.clubs c JOIN public.clubs u ON u.id=c.union_id AND u.is_union WHERE c.id=p_club
   UNION SELECT uc.union_id FROM public.union_clubs uc JOIN public.clubs u ON u.id=uc.union_id AND u.is_union WHERE uc.club_id=p_club
 LOOP
   IF NOT sent ? target::text THEN
     PERFORM public.fn_dispatch_private_record_signal('club-roster:'||target::text,'{}'::jsonb);
     sent:=sent||to_jsonb(target::text);
     -- Local to the source transaction, including savepoint/rollback behavior.
     PERFORM set_config('ca.roster_signaled_clubs',sent::text,true);
   END IF;
 END LOOP;
EXCEPTION WHEN OTHERS THEN RAISE WARNING 'Club roster signal failed: %',SQLERRM;
END $function$

public.fn_publish_member_record_context(.def:
CREATE OR REPLACE FUNCTION public.fn_publish_member_record_context()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE u uuid;
BEGIN
 IF TG_TABLE_NAME='clubs' THEN
   IF NEW.name IS NOT DISTINCT FROM OLD.name THEN RETURN NULL; END IF;
   FOR u IN SELECT DISTINCT user_id FROM public.club_members WHERE club_id=NEW.id LOOP
     PERFORM public.fn_publish_member_record_user(u);
   END LOOP;
 ELSE
   IF ROW(NEW.status,NEW.club_id,NEW.name,NEW.stakes,NEW.tournament_id,NEW.is_deleted) IS NOT DISTINCT FROM ROW(OLD.status,OLD.club_id,OLD.name,OLD.stakes,OLD.tournament_id,OLD.is_deleted) THEN RETURN NULL; END IF;
   FOR u IN SELECT DISTINCT user_id FROM public.table_seats WHERE table_id=NEW.id AND left_at IS NULL LOOP
     PERFORM public.fn_publish_member_record_user(u);
   END LOOP;
 END IF;
 RETURN NULL;
END $function$

public.fn_publish_member_record_row().def:
CREATE OR REPLACE FUNCTION public.fn_publish_member_record_row()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE r jsonb; old_user uuid; new_user uuid; child uuid;
BEGIN
  -- UPDATE OF names a source column; only an actual row change needs delivery.
  IF TG_OP='UPDATE' AND to_jsonb(OLD) IS NOT DISTINCT FROM to_jsonb(NEW) THEN
    RETURN NULL;
  END IF;
  IF TG_OP<>'INSERT' THEN
    r:=to_jsonb(OLD); old_user:=coalesce(r->>'user_id',r->>'player_id',r->>'id')::uuid;
    PERFORM public.fn_publish_member_record_user(old_user);
    PERFORM public.fn_publish_club_roster((r->>'club_id')::uuid);
    IF TG_TABLE_NAME='club_members' THEN
      BEGIN
        PERFORM public.fn_publish_member_record_topic('member-record:'||(r->>'club_id')||':'||old_user::text,'{}'::jsonb);
        PERFORM public.fn_publish_member_record_user((r->>'agent_id')::uuid);
      EXCEPTION WHEN OTHERS THEN RAISE WARNING 'Member removal signal failed: %',SQLERRM; END;
    END IF;
  END IF;
  IF TG_OP<>'DELETE' THEN
    r:=to_jsonb(NEW); new_user:=coalesce(r->>'user_id',r->>'player_id',r->>'id')::uuid;
    PERFORM public.fn_publish_club_roster((r->>'club_id')::uuid);
    IF new_user IS DISTINCT FROM old_user THEN PERFORM public.fn_publish_member_record_user(new_user); END IF;
  END IF;
  IF TG_TABLE_NAME='profiles' THEN
  IF TG_OP='UPDATE' THEN
  IF ROW(OLD.alias,OLD.username,OLD.display_name,OLD.status,OLD.first_name,OLD.last_name,OLD.full_name,OLD.player_number) IS DISTINCT FROM
    ROW(NEW.alias,NEW.username,NEW.display_name,NEW.status,NEW.first_name,NEW.last_name,NEW.full_name,NEW.player_number) THEN
    FOR child IN SELECT DISTINCT user_id FROM public.club_members WHERE agent_id=new_user LOOP
      PERFORM public.fn_publish_member_record_user(child);
    END LOOP;
  END IF;
  END IF;
  END IF;
  RETURN NULL;
END $function$

public.fn_publish_member_record_transact.def:
CREATE OR REPLACE FUNCTION public.fn_publish_member_record_transaction()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE old_row jsonb; new_row jsonb; u uuid;
BEGIN
 IF TG_OP<>'INSERT' THEN old_row:=to_jsonb(OLD); END IF;
 IF TG_OP<>'DELETE' THEN new_row:=to_jsonb(NEW); END IF;
 IF TG_OP='UPDATE' AND old_row=new_row THEN RETURN NULL; END IF;
 FOR u IN SELECT DISTINCT x FROM unnest(ARRAY[
   (old_row->>'from_user_id')::uuid,(old_row->>'to_user_id')::uuid,
   (new_row->>'from_user_id')::uuid,(new_row->>'to_user_id')::uuid]) x WHERE x IS NOT NULL LOOP
   PERFORM public.fn_publish_member_record_user(u);
 END LOOP;
 RETURN NULL;
END $function$

public.fn_refuse_operator_move_while_set.def:
CREATE OR REPLACE FUNCTION public.fn_refuse_operator_move_while_settling()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_claims text;
BEGIN
  -- Only operator movement. Everything a TABLE does is excluded on purpose:
  -- fn_atomic_buyin writes 'mint', so a freeze that caught mints would refuse
  -- buy-ins mid-session, and a settlement freeze is not a maintenance break.
  IF NEW.transaction_type IS NULL OR NEW.transaction_type NOT IN (
       'agent_wallet_send', 'agent_wallet_claim_back', 'agent_wallet_self_stake',
       'club_bank_send', 'club_bank_claim', 'club_bank_reversal',
       'promo_wallet_send', 'commission_claim',
       'admin_adjustment', 'admin_removal'
     ) THEN
    RETURN NEW;
  END IF;

  IF NEW.club_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- The settlement runner and every server-side job move chips as
  -- service_role, and the freeze exists to protect exactly that work.
  BEGIN
    v_claims := current_setting('request.jwt.claims', TRUE);
    IF v_claims IS NOT NULL AND v_claims <> ''
       AND (v_claims::jsonb ->> 'role') = 'service_role' THEN
      RETURN NEW;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;
  IF coalesce(auth.role(), '') = 'service_role'
     OR session_user IN ('postgres', 'supabase_admin') THEN
    RETURN NEW;
  END IF;

  IF public.fn_club_settlement_frozen(NEW.club_id) THEN
    RAISE EXCEPTION
      'SETTLEMENT_FROZEN: this club is squaring its books. % was refused; it will succeed when the freeze lifts.',
      NEW.transaction_type
      USING ERRCODE = '55006',
            HINT = 'A settlement freeze stops operator transfers, not play. Nothing is lost - retry once the freeze is lifted.';
  END IF;

  RETURN NEW;
END;
$function$

public.fn_refuse_while_frozen().def:
CREATE OR REPLACE FUNCTION public.fn_refuse_while_frozen()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  col  TEXT;
  changed BOOLEAN := FALSE;
  v_claims TEXT;
BEGIN
  IF TG_OP = 'UPDATE' AND TG_NARGS > 0 THEN
    FOREACH col IN ARRAY TG_ARGV LOOP
      IF to_jsonb(NEW) -> col IS DISTINCT FROM to_jsonb(OLD) -> col THEN
        changed := TRUE;
        EXIT;
      END IF;
    END LOOP;
    IF NOT changed THEN
      RETURN NEW;
    END IF;
  END IF;

  -- ONBOARDING NEVER FREEZES (to-do #2563 item 1). A membership row carrying
  -- no chips is identity, not money. This table, INSERT only, zero balance.
  IF TG_TABLE_NAME = 'club_members' AND TG_OP = 'INSERT'
     AND COALESCE((to_jsonb(NEW) ->> 'chip_balance')::numeric, 0) = 0 THEN
    RETURN NEW;
  END IF;

  -- SIGNUP NEVER FREEZES (2026-10-16). The signup trigger creates the player
  -- wallet once, inside the auth.users INSERT, and never again; refusing it
  -- during the break left the account with no wallet for good. A new wallet
  -- holding nothing is identity, not money. This table, INSERT only, both
  -- balances zero.
  IF TG_TABLE_NAME = 'wallets' AND TG_OP = 'INSERT'
     AND COALESCE((to_jsonb(NEW) ->> 'balance')::numeric, 0) = 0
     AND COALESCE((to_jsonb(NEW) ->> 'locked_balance')::numeric, 0) = 0 THEN
    RETURN NEW;
  END IF;

  IF public.fn_freeze_bypass_active() THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  -- CHIP STANDARD (2026-09-05): A JOURNAL ROW IS THE RECORD OF A WRITE, NOT A
  -- WRITE. When a balance write was permitted (a money table outside this
  -- guard, or a permitted role), its chip_ledger leg is written by the
  -- autoledger inside that same statement, at trigger depth 2 or more.
  -- Refusing the leg while the write stands is the one outcome the standard
  -- cannot allow: 104 BBJ bank moves (9.69 chips) lost their legs this way at :55 and
  -- :00 up to 09-05 06:58 (ca_ledger_write_failures, sqlstate 55006), each one an unexplained movement on the BBJ meter. A direct
  -- INSERT on chip_ledger from a client (depth 1) is still refused.
  IF TG_TABLE_NAME = 'chip_ledger' AND pg_trigger_depth() > 1 THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  BEGIN
    v_claims := current_setting('request.jwt.claims', TRUE);
    IF v_claims IS NOT NULL AND v_claims <> ''
       AND (v_claims::jsonb ->> 'role') = 'service_role' THEN
      RETURN COALESCE(NEW, OLD);
    END IF;
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  -- The original private transaction capability, never a user-set GUC.
  -- Ordinary invoker-rights callers do not invoke this private reader.
  IF current_user='postgres' THEN
    IF smarter_private.weekly_payout_owned_money_write(TG_TABLE_NAME) THEN
      RETURN COALESCE(NEW, OLD);
    END IF;
  END IF;

  IF public.fn_platform_frozen() THEN
    RAISE EXCEPTION
      'PLATFORM_FROZEN: the platform is on a scheduled maintenance break. % on % was refused; it will succeed when play resumes.',
      TG_OP, TG_TABLE_NAME
      USING ERRCODE = '55006',
            HINT = 'Scheduled maintenance breaks run from :55 to :00. Nothing is lost - retry after the break.';
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$function$

public.fn_satellite_transfer_ledger_is_i.def:
CREATE OR REPLACE FUNCTION public.fn_satellite_transfer_ledger_is_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_source_ids uuid[] := ARRAY[]::uuid[];
  v_source_id uuid;
  v_target_id uuid;
  v_text text;
  v_row jsonb;
  v_status text;
BEGIN
 IF TG_OP='INSERT' AND TG_TABLE_NAME='chip_ledger' AND to_jsonb(NEW)->'metadata'->>'entry_kind'='launch_closing_position' THEN RETURN NEW; END IF;
  IF TG_OP<>'DELETE' AND public.fn_ca_legacy_fee_resolution_write_is_exact(TG_TABLE_NAME,TG_OP,CASE WHEN TG_OP='INSERT' THEN NULL ELSE to_jsonb(OLD) END,to_jsonb(NEW)) THEN RETURN NEW; END IF;
  IF TG_OP = 'UPDATE'
     AND (NEW.tournament_id IS DISTINCT FROM OLD.tournament_id
       OR NEW.from_entity_id IS DISTINCT FROM OLD.from_entity_id
       OR NEW.to_entity_id IS DISTINCT FROM OLD.to_entity_id
       OR NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key
       OR (NEW.metadata->>'satellite_id') IS DISTINCT FROM
          (OLD.metadata->>'satellite_id')) THEN
    RAISE EXCEPTION 'satellite transfer journal ownership is immutable'
      USING ERRCODE = '55000';
  END IF;
  FOREACH v_row IN ARRAY ARRAY[
    CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE to_jsonb(OLD) END,
    CASE WHEN TG_OP = 'DELETE' THEN NULL ELSE to_jsonb(NEW) END
  ] LOOP
    IF v_row IS NULL THEN CONTINUE; END IF;
    v_text := v_row->>'tournament_id';
    IF v_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_source_ids := array_append(v_source_ids,v_text::uuid);
    END IF;
    IF v_row->>'from_type' = 'prize_liability' THEN
      v_text := v_row->>'from_entity_id';
      IF v_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        v_source_ids := array_append(v_source_ids,v_text::uuid);
      END IF;
    END IF;
    v_text := split_part(COALESCE(v_row->>'idempotency_key',''),':',2);
    IF COALESCE(v_row->>'idempotency_key','') LIKE 'tourney:%:seat:%:pool_transfer'
       AND v_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_source_ids := array_append(v_source_ids,v_text::uuid);
    END IF;
    v_text := v_row->'metadata'->>'satellite_id';
    IF v_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_source_ids := array_append(v_source_ids,v_text::uuid);
    END IF;
  END LOOP;
  IF TG_OP <> 'INSERT' AND cardinality(v_source_ids) > 0 THEN
    RAISE EXCEPTION 'satellite transfer journal is append-only'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'INSERT' AND NEW.to_type = 'prize_liability' THEN
    SELECT t.id INTO v_target_id FROM public.tournaments t
     WHERE t.id = NEW.to_entity_id;
    IF v_target_id IS NOT NULL THEN
      -- The transfer's AFTER trigger writes target escrow, so own the target
      -- before any source root exactly as fn_settle_satellite_tournament does.
      SELECT upper(COALESCE(t.status::text,'')) INTO v_status
        FROM public.tournaments t
       WHERE t.id = v_target_id FOR SHARE;
      IF v_status IN ('COMPLETED','CANCELLED','CANCELED') THEN
        RAISE EXCEPTION 'terminal target cannot accept a satellite transfer journal'
          USING ERRCODE = '55000';
      END IF;
    END IF;
  END IF;
  FOR v_source_id IN
    SELECT DISTINCT source.id FROM unnest(v_source_ids) source(id)
     WHERE source.id IS NOT NULL ORDER BY source.id
  LOOP
    IF TG_OP = 'INSERT' AND v_source_id IS DISTINCT FROM v_target_id THEN
      SELECT upper(COALESCE(t.status::text,'')) INTO v_status
        FROM public.tournaments t
       WHERE t.id = v_source_id FOR SHARE;
      IF v_status IN ('COMPLETED','CANCELLED','CANCELED') THEN
        RAISE EXCEPTION 'completed satellite transfer journal is immutable'
          USING ERRCODE = '55000';
      END IF;
    END IF;
    IF public.fn_ca_has_committed_tournament_receipt(v_source_id) THEN
      RAISE EXCEPTION 'completed satellite transfer journal is immutable'
        USING ERRCODE = '55000';
    END IF;
  END LOOP;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$

public.fn_settle_accounting_rakeback_sta.def:
CREATE OR REPLACE FUNCTION public.fn_settle_accounting_rakeback_stage(p_scope_kind text, p_scope_id uuid, p_period_start timestamp with time zone, p_period_end timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE prior_plan jsonb;prior_item record;prior_saved_context text;legacy_paid_cash_replay boolean:=false;scope record;p_union_id uuid;standalone_club uuid;
 r record;c public.accounting_rakeback_period_calculations%ROWTYPE;g record;
 previous public.accounting_routed_settlement_runs%ROWTYPE;fingerprint text;result jsonb;
 from_date date;to_date date;allocation_count int;matched_count int;actual_count int;
 generated numeric;unrounded numeric;display_rate numeric;amount numeric;paid numeric:=0;
 payer_before numeric;payer_after numeric;player_before numeric;player_after numeric;
 payout_id uuid;wallet_id uuid;ledger_id uuid;receipt_count int;payees int:=0;
 club_skip text;member_skip text;maintenance text;routing_context text;agent_skip text;v4_ok boolean:=false;
 v_plan jsonb;v_plan_used boolean:=false;v_batched boolean:=false;v_stop timestamptz;v_remaining bigint:=0;
 v_paid_before numeric:=0;v_payees_before int:=0;
 deleted_deferral text; v_deleted record; v_deleted_before numeric; v_deleted_held numeric; v_deleted_locked numeric;
 v_deleted_bank numeric; v_deleted_return jsonb;
BEGIN
 IF NOT public.fn_caller_is_engine() THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501'; END IF;
 IF p_period_start IS NULL OR p_period_end IS NULL OR NOT isfinite(p_period_start) OR NOT isfinite(p_period_end)
  OR p_period_start>=p_period_end OR p_period_end>now()-interval '5 minutes' THEN RAISE EXCEPTION 'routed_rakeback_invalid_period' USING ERRCODE='22023'; END IF;
 IF public.fn_ca_launch_accounting_waived(p_scope_kind,p_scope_id,p_period_end) THEN
  RETURN jsonb_build_object('success',true,'waived',true,'paid',false,'reason','owner_directed_launch_waiver');
 END IF;
 SELECT * INTO scope FROM public.fn_resolve_accounting_routing_scope(p_scope_kind,p_scope_id,p_period_start,p_period_end);
 p_union_id:=scope.union_id;standalone_club:=scope.standalone_club_id;
 IF p_union_id IS NOT NULL THEN PERFORM public.fn_accounting_union_earned_plan(p_union_id,p_period_start,p_period_end); END IF;
 IF EXISTS(SELECT 1 FROM public.settlement_locks WHERE lock_type='GLOBAL_SETTLEMENT_FREEZE' AND is_active) THEN RAISE EXCEPTION 'EMERGENCY_PROFIT_DRIFT_LOCK'; END IF;
 IF EXISTS(SELECT 1 FROM public.union_settlement_floor WHERE union_id=p_union_id AND p_period_start<earliest_period_start)
  OR NOT EXISTS(SELECT 1 FROM public.accounting_cash_accrual_cutover WHERE singleton AND p_period_start>=starts_at)
 THEN RAISE EXCEPTION 'routed_rakeback_historical_period_uncertified' USING ERRCODE='55000'; END IF;
 from_date:=(p_period_start AT TIME ZONE 'America/Los_Angeles')::date;
 to_date:=(p_period_end AT TIME ZONE 'America/Los_Angeles')::date-1;
 IF p_period_start IS DISTINCT FROM public.fn_union_week_start(p_period_start)
  OR p_period_end IS DISTINCT FROM public.fn_union_week_start(p_period_start+interval '8 days')
 THEN RAISE EXCEPTION 'routed_rakeback_requires_one_accounting_week' USING ERRCODE='22023'; END IF;
 PERFORM smarter_private.assert_own_agent_scope_interpreted(p_scope_kind,p_scope_id,p_period_start,p_period_end,3);
 PERFORM public.fn_lock_rakeback_payer_clubs(scope.club_ids);
 SELECT * INTO previous FROM public.accounting_routed_settlement_runs
  WHERE scope_kind=p_scope_kind AND scope_id=p_scope_id AND period_start=p_period_start AND period_end=p_period_end AND round_no=3;
 -- Only a completed cash-only run can read its original untyped allocation
 -- again. Pending certificates need explicit source types before any payment.
 legacy_paid_cash_replay:=FOUND AND previous.routing_version=3 AND previous.result->>'source_version'='2'
  AND NOT(previous.result ? 'source_contract_version');
 CREATE TEMP TABLE IF NOT EXISTS _routed_player_items(period_id uuid PRIMARY KEY,certificate_id bigint,club_id uuid,user_id uuid,
  payer_kind text,payer_user uuid,owed numeric,rake numeric,rate numeric,fingerprint text,status text) ON COMMIT DROP;
 TRUNCATE pg_temp._routed_player_items;
 -- CHUNKED CLOSE (20261003, round 3 read once): in a chunked close attempt the
 -- week's reads and allocation tests may come from the attempt that read them
 -- (fn_settle_accounting_rakeback_plan); see below for when they are used.
 v_plan:=public.fn_settle_accounting_rakeback_plan_get(p_scope_kind,p_scope_id,p_period_start,p_period_end,scope.club_ids,p_union_id,standalone_club,legacy_paid_cash_replay);
 CREATE TEMP TABLE IF NOT EXISTS _rr3_plan_nonhouse(club_id uuid,player_id uuid,PRIMARY KEY(club_id,player_id)) ON COMMIT DROP;
 TRUNCATE pg_temp._rr3_plan_nonhouse;
 CREATE TEMP TABLE IF NOT EXISTS _rr3_week_v4(source_type text,source_id uuid,club_id uuid,player_id uuid,coordinator_union_id uuid,earned_at timestamptz,
    rake_credit numeric,rake_record_id uuid,agent_text text,house_text text,PRIMARY KEY(source_type,source_id)) ON COMMIT DROP;
 -- WEEKLY CLOSE SCALE (20260928): the per-period proof, read as sets. The
 -- periods are locked in the original order; the latest certificate of each,
 -- every allocation of every certificate and this scope's sources of the week
 -- are each read once, and every original test is evaluated on them. Only a
 -- book that passes every test takes this path. Any refusal, and anything
 -- this path cannot read, runs the original per-period loop below, unchanged,
 -- which raises exactly what it always raised.
 BEGIN
  CREATE TEMP TABLE IF NOT EXISTS _rr3_periods_v4(ord bigint,LIKE public.rakeback_periods) ON COMMIT DROP;
  TRUNCATE pg_temp._rr3_periods_v4;
  -- WEEKLY CLOSE SCALE (20261003): a period of a club outside scope.club_ids
  -- is admitted when this scope earned from its player in the week. Those
  -- (club, player) pairs are read once, for exactly the clubs of such
  -- periods, in this same statement, instead of a scan of the club's whole
  -- week of sources per period (887 s in the 2026-10-01 Midway close: 382
  -- standalone periods). A period whose club is not in that set (only a row
  -- changed under EvalPlanQual) still asks the sources directly.
  INSERT INTO pg_temp._rr3_periods_v4 SELECT row_number() OVER(ORDER BY x.club_id,x.user_id,x.id),x.*
   FROM (WITH pclubs AS MATERIALIZED (SELECT DISTINCT p2.club_id FROM public.rakeback_periods p2
      WHERE p2.period_start<=to_date AND p2.period_end>=from_date AND p2.club_id IS NOT NULL AND (p2.club_id=ANY(scope.club_ids)) IS NOT TRUE),
    pairs AS MATERIALIZED (SELECT DISTINCT rs.club_id,rs.player_id FROM public.accounting_payable_earning_sources rs
      WHERE rs.club_id IN(SELECT pc.club_id FROM pclubs pc)
      AND (rs.coordinator_union_id=p_union_id OR (standalone_club IS NOT NULL AND rs.coordinator_union_id IS NULL AND rs.club_id=standalone_club)) AND rs.earned_at>=p_period_start AND rs.earned_at<p_period_end
      AND v_plan IS NULL
     UNION SELECT (e->>0)::uuid,(e->>1)::uuid FROM jsonb_array_elements(v_plan->'pairs') e
      WHERE v_plan IS NOT NULL AND (e->>0)::uuid IN(SELECT pc.club_id FROM pclubs pc))
   SELECT rp.* FROM public.rakeback_periods rp WHERE rp.period_start<=to_date AND rp.period_end>=from_date
  -- A standalone book never owns a valid Union certificate without any of
  -- its own original earning sources. Unknown certificates remain admitted
  -- to the original refusal path; any standalone source defeats exclusion.
  -- The identical certificate tests are read once per close as one set
  -- (fn_standalone_foreign_certificate_periods), never once per period.
  AND NOT(p_scope_kind='club' AND rp.club_id=standalone_club
    AND rp.period_start=from_date AND rp.period_end=to_date
    AND rp.id IN(SELECT foreign_set.period_id FROM public.fn_standalone_foreign_certificate_periods(
      p_scope_kind,standalone_club,from_date,to_date,p_period_start,p_period_end)foreign_set))
  AND (rp.club_id=ANY(scope.club_ids)
    OR CASE WHEN rp.club_id IN(SELECT pc.club_id FROM pclubs pc)
     THEN EXISTS(SELECT 1 FROM pairs q WHERE q.club_id=rp.club_id AND q.player_id=rp.user_id)
     ELSE EXISTS(SELECT 1 FROM public.accounting_payable_earning_sources rs WHERE rs.club_id=rp.club_id AND rs.player_id=rp.user_id
      AND (rs.coordinator_union_id=p_union_id OR (standalone_club IS NOT NULL AND rs.coordinator_union_id IS NULL AND rs.club_id=standalone_club)) AND rs.earned_at>=p_period_start AND rs.earned_at<p_period_end) END)
  ORDER BY rp.club_id,rp.user_id,rp.id FOR UPDATE OF rp) x;
  CREATE TEMP TABLE IF NOT EXISTS _rr3_certs_v4(period_id uuid PRIMARY KEY,id bigint,accounting_version integer,source_fingerprint text,club_id uuid,player_id uuid,
   coordinator_union_id uuid,period_start date,period_end date,rake_generated numeric,rakeback_amount numeric,display_rate numeric,payer_kind text,payer_user_id uuid) ON COMMIT DROP;
  TRUNCATE pg_temp._rr3_certs_v4;
  INSERT INTO pg_temp._rr3_certs_v4 SELECT DISTINCT ON(x.period_id) x.period_id,x.id,x.accounting_version,x.source_fingerprint,x.club_id,x.player_id,
   x.coordinator_union_id,x.period_start,x.period_end,x.rake_generated,x.rakeback_amount,x.display_rate,x.payer_kind,x.payer_user_id
   FROM public.accounting_rakeback_period_calculations x WHERE x.period_id IN(SELECT id FROM pg_temp._rr3_periods_v4) ORDER BY x.period_id,x.id DESC;
  IF (SELECT count(*) FROM pg_temp._rr3_periods_v4 pr LEFT JOIN pg_temp._rr3_certs_v4 pc ON pc.period_id=pr.id
    WHERE COALESCE(pc.id IS NULL OR pc.accounting_version<>2 OR pc.coordinator_union_id IS DISTINCT FROM p_union_id OR pr.period_start<>from_date OR pr.period_end<>to_date
   OR pc.club_id IS DISTINCT FROM pr.club_id OR pc.player_id IS DISTINCT FROM pr.user_id
   OR pc.period_start IS DISTINCT FROM pr.period_start OR pc.period_end IS DISTINCT FROM pr.period_end
   OR pc.rake_generated IS DISTINCT FROM pr.rake_generated OR pc.rake_generated IS DISTINCT FROM pr.total_rake_paid
   OR pc.rakeback_amount IS DISTINCT FROM pr.rakeback_amount OR pc.rakeback_amount IS DISTINCT FROM pr.rakeback_earned
   OR pc.display_rate IS DISTINCT FROM pr.rakeback_rate OR pc.rakeback_amount<0 OR pc.rakeback_amount<>round(pc.rakeback_amount,2)
   OR pc.rakeback_amount::text IN('NaN','Infinity','-Infinity') OR pc.payer_kind NOT IN('agent','club','split')
   OR (pc.payer_kind='agent') IS DISTINCT FROM(pc.payer_user_id IS NOT NULL) OR pc.payer_user_id=pr.user_id,false))=0 THEN
   CREATE TEMP TABLE IF NOT EXISTS _rr3_wn_v4(club_id uuid,player_id uuid,n bigint,PRIMARY KEY(club_id,player_id)) ON COMMIT DROP;
   TRUNCATE pg_temp._rr3_wn_v4;
   IF v_plan IS NOT NULL THEN
    CREATE TEMP TABLE IF NOT EXISTS _rr3_plan_alloc(period_id uuid PRIMARY KEY,cert_id bigint,club_id uuid,user_id uuid,allocation_count bigint,matched_count bigint,
     generated numeric,unrounded numeric,any_bad boolean) ON COMMIT DROP;
    TRUNCATE pg_temp._rr3_plan_alloc;
    INSERT INTO pg_temp._rr3_plan_alloc SELECT (e->>0)::uuid,(e->>1)::bigint,(e->>2)::uuid,(e->>3)::uuid,(e->>4)::bigint,(e->>5)::bigint,
     (e->>6)::numeric,(e->>7)::numeric,(e->>8)::boolean FROM jsonb_array_elements(v_plan->'alloc') e;
    IF NOT EXISTS(SELECT 1 FROM pg_temp._rr3_periods_v4 pr JOIN pg_temp._rr3_certs_v4 pc ON pc.period_id=pr.id
      WHERE NOT EXISTS(SELECT 1 FROM pg_temp._rr3_plan_alloc a WHERE a.period_id=pr.id AND a.cert_id=pc.id AND a.club_id=pr.club_id AND a.user_id=pr.user_id)) THEN
     v_plan_used:=true;
    END IF;
   END IF;
   IF NOT v_plan_used THEN
   CREATE TEMP TABLE IF NOT EXISTS _rr3_week_v4(source_type text,source_id uuid,club_id uuid,player_id uuid,coordinator_union_id uuid,earned_at timestamptz,
    rake_credit numeric,rake_record_id uuid,agent_text text,house_text text,PRIMARY KEY(source_type,source_id)) ON COMMIT DROP;
   TRUNCATE pg_temp._rr3_week_v4;
   -- house_text (20261003): the source's is_union_house as written, read in
   -- this one pass so the missing-period check below need not read the week
   -- of sources again.
   INSERT INTO pg_temp._rr3_week_v4 SELECT rs.source_type,rs.source_id,rs.club_id,rs.player_id,rs.coordinator_union_id,rs.earned_at,rs.rake_credit,rs.rake_record_id,
    (CASE WHEN (((rs.contract#>>'{membership,terms,player_rakeback_pct}')::numeric=0.70 OR rs.contract->'tiers'->0 IS NULL) AND EXISTS(SELECT 1 FROM public.clubs owner_club WHERE owner_club.id=rs.club_id AND owner_club.owner_id=NULLIF(rs.contract#>>'{membership,terms,agent_id}','')::uuid)) THEN NULL::uuid ELSE NULLIF(rs.contract#>>'{membership,terms,agent_id}','')::uuid END)::text,rs.contract->>'is_union_house'
    FROM public.accounting_payable_earning_sources rs WHERE rs.earned_at>=p_period_start AND rs.earned_at<p_period_end
     AND (rs.coordinator_union_id=p_union_id OR (standalone_club IS NOT NULL AND rs.coordinator_union_id IS NULL AND rs.club_id=standalone_club));
   ANALYZE pg_temp._rr3_week_v4;
   END IF;
   CREATE TEMP TABLE IF NOT EXISTS _rr3_alloc_v4(period_id uuid PRIMARY KEY,allocation_count bigint,matched_count bigint,generated numeric,unrounded numeric,any_bad boolean) ON COMMIT DROP;
   TRUNCATE pg_temp._rr3_alloc_v4;
   -- A source of this allocation that is not in this scope's week slice is
   -- outside the scope or the week, which the original test refuses too.
   IF v_plan_used THEN
    INSERT INTO pg_temp._rr3_alloc_v4 SELECT a.period_id,a.allocation_count,a.matched_count,a.generated,a.unrounded,a.any_bad
     FROM pg_temp._rr3_plan_alloc a JOIN pg_temp._rr3_certs_v4 pc ON pc.period_id=a.period_id AND pc.id=a.cert_id;
    INSERT INTO pg_temp._rr3_wn_v4 SELECT (e->>0)::uuid,(e->>1)::uuid,(e->>2)::bigint FROM jsonb_array_elements(v_plan->'counts') e;
    INSERT INTO pg_temp._rr3_plan_nonhouse SELECT (e->>0)::uuid,(e->>1)::uuid FROM jsonb_array_elements(v_plan->'nonhouse') e;
   ELSE
   INSERT INTO pg_temp._rr3_alloc_v4 SELECT pc.period_id,count(*),
    count(DISTINCT ROW(COALESCE(a->>'source_type',CASE WHEN legacy_paid_cash_replay THEN 'cash_rake_accrual' END),a->>'source_id')),
    sum((a->>'rake_credit')::numeric),sum((a->>'rake_credit')::numeric*(a->>'rate')::numeric),
    COALESCE(bool_or(COALESCE(a->>'source_type',CASE WHEN legacy_paid_cash_replay THEN 'cash_rake_accrual' END) IS NULL OR COALESCE(a->>'source_type',CASE WHEN legacy_paid_cash_replay THEN 'cash_rake_accrual' END) NOT IN('cash_rake_accrual','tournament_fee_accrual')
      OR rs.source_id IS NULL OR rs.club_id<>pr.club_id OR rs.player_id<>pr.user_id OR rs.coordinator_union_id IS DISTINCT FROM p_union_id
      OR rs.earned_at<p_period_start OR rs.earned_at>=p_period_end OR rs.rake_credit IS DISTINCT FROM(a->>'rake_credit')::numeric
      OR rs.rake_record_id IS DISTINCT FROM(a->>'rake_record_id')::uuid
      OR (a->>'rate')::numeric IS NULL OR (a->>'rate')::numeric<0 OR (a->>'rate')::numeric>1
      OR (a->>'rate')::numeric::text IN('NaN','Infinity','-Infinity')
      OR (pc.payer_kind<>'split' AND(a->>'payer_kind' IS DISTINCT FROM pc.payer_kind OR NULLIF(a->>'payer_user_id','')::uuid IS DISTINCT FROM pc.payer_user_id)) OR (pc.payer_kind='split' AND(a->>'payer_kind' NOT IN('agent','club') OR(a->>'payer_kind'='agent') IS DISTINCT FROM(NULLIF(a->>'payer_user_id','')IS NOT NULL)))
      OR NULLIF(rs.agent_text,'')::uuid IS DISTINCT FROM NULLIF(a->>'payer_user_id','')::uuid),false)
    FROM pg_temp._rr3_certs_v4 pc JOIN pg_temp._rr3_periods_v4 pr ON pr.id=pc.period_id
    JOIN public.accounting_rakeback_period_calculations cc ON cc.id=pc.id
    CROSS JOIN LATERAL jsonb_array_elements(cc.source_allocations) a
    LEFT JOIN pg_temp._rr3_week_v4 rs ON rs.source_type=COALESCE(a->>'source_type',CASE WHEN legacy_paid_cash_replay THEN 'cash_rake_accrual' END) AND rs.source_id=(a->>'source_id')::uuid
    GROUP BY pc.period_id;
   INSERT INTO pg_temp._rr3_wn_v4 SELECT w.club_id,w.player_id,count(*) FROM pg_temp._rr3_week_v4 w GROUP BY w.club_id,w.player_id;
   END IF;
   IF (SELECT count(*) FROM pg_temp._rr3_periods_v4 pr JOIN pg_temp._rr3_certs_v4 pc ON pc.period_id=pr.id
     LEFT JOIN pg_temp._rr3_alloc_v4 ag ON ag.period_id=pr.id
     LEFT JOIN pg_temp._rr3_wn_v4 w ON w.club_id=pr.club_id AND w.player_id=pr.user_id
     WHERE COALESCE((COALESCE(ag.allocation_count,0)=0 OR COALESCE(ag.allocation_count,0)<>COALESCE(ag.matched_count,0) OR COALESCE(ag.allocation_count,0)<>COALESCE(w.n,0)
       OR ag.generated IS DISTINCT FROM pc.rake_generated
       OR round(ag.unrounded,2) IS DISTINCT FROM pc.rakeback_amount
       OR pc.display_rate IS DISTINCT FROM (CASE WHEN ag.generated>0 THEN round(ag.unrounded/ag.generated,4) ELSE 0 END))
      OR COALESCE(ag.any_bad,false),false))=0 THEN
    INSERT INTO pg_temp._routed_player_items SELECT pr.id,pc.id,pr.club_id,pr.user_id,pc.payer_kind,pc.payer_user_id,pc.rakeback_amount,pc.rake_generated,pc.display_rate,pc.source_fingerprint,pr.status
     FROM pg_temp._rr3_periods_v4 pr JOIN pg_temp._rr3_certs_v4 pc ON pc.period_id=pr.id;
    v4_ok:=true;
   END IF;
  END IF;
 EXCEPTION WHEN OTHERS THEN v4_ok:=false;
 END;
 IF NOT v4_ok THEN
 TRUNCATE pg_temp._routed_player_items;
 FOR r IN SELECT rp.* FROM public.rakeback_periods rp WHERE rp.period_start<=to_date AND rp.period_end>=from_date
  -- A standalone book never owns a valid Union certificate without any of
  -- its own original earning sources. Unknown certificates remain admitted
  -- to the original refusal path; any standalone source defeats exclusion.
  -- The identical certificate tests are read once per close as one set
  -- (fn_standalone_foreign_certificate_periods), never once per period.
  AND NOT(p_scope_kind='club' AND rp.club_id=standalone_club
    AND rp.period_start=from_date AND rp.period_end=to_date
    AND rp.id IN(SELECT foreign_set.period_id FROM public.fn_standalone_foreign_certificate_periods(
      p_scope_kind,standalone_club,from_date,to_date,p_period_start,p_period_end)foreign_set))
  AND (rp.club_id=ANY(scope.club_ids)
    OR EXISTS(SELECT 1 FROM public.accounting_payable_earning_sources rs WHERE rs.club_id=rp.club_id AND rs.player_id=rp.user_id
      AND (rs.coordinator_union_id=p_union_id OR (standalone_club IS NOT NULL AND rs.coordinator_union_id IS NULL AND rs.club_id=standalone_club)) AND rs.earned_at>=p_period_start AND rs.earned_at<p_period_end))
  ORDER BY rp.club_id,rp.user_id,rp.id FOR UPDATE
 LOOP
  SELECT * INTO c FROM public.accounting_rakeback_period_calculations WHERE period_id=r.id ORDER BY id DESC LIMIT 1;
  IF NOT FOUND OR c.accounting_version<>2 OR c.coordinator_union_id IS DISTINCT FROM p_union_id OR r.period_start<>from_date OR r.period_end<>to_date
   OR c.club_id IS DISTINCT FROM r.club_id OR c.player_id IS DISTINCT FROM r.user_id
   OR c.period_start IS DISTINCT FROM r.period_start OR c.period_end IS DISTINCT FROM r.period_end
   OR c.rake_generated IS DISTINCT FROM r.rake_generated OR c.rake_generated IS DISTINCT FROM r.total_rake_paid
   OR c.rakeback_amount IS DISTINCT FROM r.rakeback_amount OR c.rakeback_amount IS DISTINCT FROM r.rakeback_earned
   OR c.display_rate IS DISTINCT FROM r.rakeback_rate OR c.rakeback_amount<0 OR c.rakeback_amount<>round(c.rakeback_amount,2)
   OR c.rakeback_amount::text IN('NaN','Infinity','-Infinity') OR c.payer_kind NOT IN('agent','club','split')
   OR (c.payer_kind='agent') IS DISTINCT FROM(c.payer_user_id IS NOT NULL) OR c.payer_user_id=r.user_id
  THEN RAISE EXCEPTION 'routed_rakeback_certificate_required' USING ERRCODE='55000'; END IF;
  SELECT count(*),count(DISTINCT ROW(COALESCE(a->>'source_type',CASE WHEN legacy_paid_cash_replay THEN 'cash_rake_accrual' END),a->>'source_id')),sum((a->>'rake_credit')::numeric),sum((a->>'rake_credit')::numeric*(a->>'rate')::numeric)
   INTO allocation_count,matched_count,generated,unrounded FROM jsonb_array_elements(c.source_allocations) a;
  SELECT count(*) INTO actual_count FROM public.accounting_payable_earning_sources rs WHERE rs.club_id=r.club_id AND rs.player_id=r.user_id
   AND rs.earned_at>=p_period_start AND rs.earned_at<p_period_end AND (rs.coordinator_union_id=p_union_id OR (standalone_club IS NOT NULL AND rs.coordinator_union_id IS NULL AND rs.club_id=standalone_club));
  IF allocation_count=0 OR allocation_count<>matched_count OR allocation_count<>actual_count OR generated IS DISTINCT FROM c.rake_generated
    OR round(unrounded,2) IS DISTINCT FROM c.rakeback_amount
    OR c.display_rate IS DISTINCT FROM (CASE WHEN generated>0 THEN round(unrounded/generated,4) ELSE 0 END)
    OR EXISTS(SELECT 1 FROM jsonb_array_elements(c.source_allocations) a LEFT JOIN public.accounting_payable_earning_sources rs ON rs.source_type=COALESCE(a->>'source_type',CASE WHEN legacy_paid_cash_replay THEN 'cash_rake_accrual' END) AND rs.source_id=(a->>'source_id')::uuid
     WHERE COALESCE(a->>'source_type',CASE WHEN legacy_paid_cash_replay THEN 'cash_rake_accrual' END) IS NULL OR COALESCE(a->>'source_type',CASE WHEN legacy_paid_cash_replay THEN 'cash_rake_accrual' END) NOT IN('cash_rake_accrual','tournament_fee_accrual')
      OR rs.source_id IS NULL OR rs.club_id<>r.club_id OR rs.player_id<>r.user_id OR rs.coordinator_union_id IS DISTINCT FROM p_union_id
      OR rs.earned_at<p_period_start OR rs.earned_at>=p_period_end OR rs.rake_credit IS DISTINCT FROM(a->>'rake_credit')::numeric
      OR rs.rake_record_id IS DISTINCT FROM(a->>'rake_record_id')::uuid
      OR (a->>'rate')::numeric IS NULL OR (a->>'rate')::numeric<0 OR (a->>'rate')::numeric>1
      OR (a->>'rate')::numeric::text IN('NaN','Infinity','-Infinity')
      OR (c.payer_kind<>'split' AND(a->>'payer_kind' IS DISTINCT FROM c.payer_kind OR NULLIF(a->>'payer_user_id','')::uuid IS DISTINCT FROM c.payer_user_id)) OR (c.payer_kind='split' AND(a->>'payer_kind' NOT IN('agent','club') OR(a->>'payer_kind'='agent') IS DISTINCT FROM(NULLIF(a->>'payer_user_id','')IS NOT NULL)))
      OR (CASE WHEN (((rs.contract#>>'{membership,terms,player_rakeback_pct}')::numeric=0.70 OR rs.contract->'tiers'->0 IS NULL) AND EXISTS(SELECT 1 FROM public.clubs owner_club WHERE owner_club.id=rs.club_id AND owner_club.owner_id=NULLIF(rs.contract#>>'{membership,terms,agent_id}','')::uuid)) THEN NULL::uuid ELSE NULLIF(rs.contract#>>'{membership,terms,agent_id}','')::uuid END) IS DISTINCT FROM NULLIF(a->>'payer_user_id','')::uuid)
  THEN RAISE EXCEPTION 'routed_rakeback_sources_disagree_with_certificate' USING ERRCODE='23514'; END IF;
  INSERT INTO pg_temp._routed_player_items VALUES(r.id,c.id,r.club_id,r.user_id,c.payer_kind,c.payer_user_id,c.rakeback_amount,c.rake_generated,c.display_rate,c.source_fingerprint,r.status);
 END LOOP;
 END IF;
 -- Missing periods are obligations too: every source player in this scope must
 -- have an admitted certificate, including zero-entitlement players.
 -- 20261003: when the set path admitted the book, _rr3_week_v4 holds exactly
 -- these rows (same predicate, read under this scope's week lock, which every
 -- accrual of the week shares), so they are not read a second time.
 PERFORM set_config('app.accounting_round3_plan_used',CASE WHEN v4_ok AND v_plan_used THEN 'on' ELSE '' END,true);
 IF (CASE WHEN v4_ok AND v_plan_used THEN EXISTS(SELECT 1 FROM pg_temp._rr3_plan_nonhouse rs
     WHERE NOT EXISTS(SELECT 1 FROM pg_temp._routed_player_items i WHERE i.club_id=rs.club_id AND i.user_id=rs.player_id))
  WHEN v4_ok THEN EXISTS(SELECT 1 FROM pg_temp._rr3_week_v4 rs
    WHERE COALESCE((rs.house_text)::boolean,false) IS FALSE
     AND NOT EXISTS(SELECT 1 FROM pg_temp._routed_player_items i WHERE i.club_id=rs.club_id AND i.user_id=rs.player_id))
  ELSE EXISTS(SELECT 1 FROM public.accounting_payable_earning_sources rs WHERE (rs.coordinator_union_id=p_union_id OR (standalone_club IS NOT NULL AND rs.coordinator_union_id IS NULL AND rs.club_id=standalone_club))
   AND rs.earned_at>=p_period_start AND rs.earned_at<p_period_end
   AND COALESCE((rs.contract->>'is_union_house')::boolean,false) IS FALSE
   AND NOT EXISTS(SELECT 1 FROM pg_temp._routed_player_items i WHERE i.club_id=rs.club_id AND i.user_id=rs.player_id)) END)
 THEN RAISE EXCEPTION 'routed_rakeback_player_period_missing' USING ERRCODE='55000'; END IF;
 SELECT md5(COALESCE(jsonb_agg(jsonb_build_array(i.period_id,i.certificate_id,i.club_id,i.user_id,i.payer_kind,i.payer_user,i.owed,i.rake,i.rate,i.fingerprint) ORDER BY i.period_id),'[]'::jsonb)::text)
  INTO fingerprint FROM pg_temp._routed_player_items i;
 SELECT * INTO previous FROM public.accounting_routed_settlement_runs
  WHERE scope_kind=p_scope_kind AND scope_id=p_scope_id AND period_start=p_period_start AND period_end=p_period_end AND round_no=3;
 IF FOUND THEN
  IF EXISTS(SELECT FROM smarter_private.existing_rakeback_transfer_allocations a JOIN pg_temp._routed_player_items i ON i.period_id=a.obligation_id WHERE a.obligation_role='player'AND NOT smarter_private.existing_rakeback_transfer_complete('player',i.period_id)) OR previous.source_fingerprint<>fingerprint OR EXISTS(SELECT 1 FROM pg_temp._routed_player_items i WHERE i.status<>'paid' OR NOT EXISTS(
   SELECT 1 FROM public.rakeback_period_payouts pp WHERE pp.rakeback_period_id=i.period_id AND pp.user_id=i.user_id AND pp.club_id=i.club_id AND pp.status='paid' AND pp.payout_amount=i.owed AND(CASE WHEN EXISTS(SELECT FROM public.accounting_rakeback_wallet_contracts wc WHERE wc.calculation_id=i.certificate_id) THEN smarter_private.rakeback_wallet_payout_complete(pp.id,i.certificate_id) WHEN i.payer_kind='split' THEN smarter_private.split_rakeback_payout_complete(pp.id,i.certificate_id) ELSE true END)))
  THEN RAISE EXCEPTION 'routed_rakeback_changed_after_payment' USING ERRCODE='55000'; END IF;
  RETURN previous.result||jsonb_build_object('duplicate',true);
 END IF;
 -- CHUNKED CLOSE (20261003, round 3 in batches): inside a chunked close attempt
 -- a period an earlier batch of THIS round paid is recognised by its own
 -- evidence and not paid again; outside one nothing is.
  PERFORM smarter_private.weekly_payout_require_round(p_scope_kind,p_scope_id,p_period_start,p_period_end,3);
 v_batched:=COALESCE(current_setting('app.weekly_accounting_chunked',true),'')='on'
  AND NULLIF(current_setting('app.weekly_accounting_scope_deadline',true),'') IS NOT NULL;
 CREATE TEMP TABLE IF NOT EXISTS _routed_player_done(period_id uuid PRIMARY KEY) ON COMMIT DROP;
 TRUNCATE pg_temp._routed_player_done;
 IF EXISTS(SELECT FROM pg_temp._routed_player_items i JOIN smarter_private.existing_rakeback_transfer_allocations a ON a.obligation_role='player'AND a.obligation_id=i.period_id WHERE NOT smarter_private.existing_rakeback_transfer_complete('player',i.period_id)) THEN RAISE EXCEPTION 'existing_transfer_discharge_receipt_incomplete' USING ERRCODE='23514';END IF;
 INSERT INTO pg_temp._routed_player_done SELECT i.period_id FROM pg_temp._routed_player_items i JOIN smarter_private.existing_rakeback_transfer_allocations a ON a.obligation_role='player'AND a.obligation_id=i.period_id WHERE smarter_private.existing_rakeback_transfer_complete('player',i.period_id);
 IF v_batched THEN
  INSERT INTO pg_temp._routed_player_done SELECT i.period_id FROM pg_temp._routed_player_items i
   WHERE i.status='paid' AND (SELECT count(*) FROM public.rakeback_period_payouts pp WHERE pp.rakeback_period_id=i.period_id)=1
    AND EXISTS(SELECT 1 FROM public.rakeback_period_payouts pp WHERE pp.rakeback_period_id=i.period_id AND pp.club_id=i.club_id AND pp.user_id=i.user_id
     AND pp.status='paid' AND pp.payout_amount=i.owed
     AND CASE WHEN EXISTS(SELECT FROM public.accounting_rakeback_wallet_contracts wc WHERE wc.calculation_id=i.certificate_id) THEN smarter_private.rakeback_wallet_payout_complete(pp.id,i.certificate_id) WHEN i.payer_kind='split' THEN smarter_private.split_rakeback_payout_complete(pp.id,i.certificate_id) WHEN i.owed>0 THEN EXISTS(SELECT 1 FROM public.chip_ledger l WHERE l.idempotency_key='round3-period:v3:'||i.period_id::text
       AND l.amount=i.owed AND l.club_id=i.club_id AND l.to_type='player_wallet' AND l.to_entity_id=i.user_id AND l.category='rakeback'
       AND l.metadata->>'accounting_scope_kind'=p_scope_kind AND l.metadata->>'accounting_scope_id'=p_scope_id::text
       AND l.metadata->>'certificate_id'=i.certificate_id::text AND l.metadata->>'payout_id'=pp.id::text
       AND l.metadata->>'source_fingerprint' IS NOT DISTINCT FROM i.fingerprint) ELSE true END) ON CONFLICT DO NOTHING;
 END IF;
 CREATE TEMP TABLE IF NOT EXISTS _routed_player_todo(LIKE pg_temp._routed_player_items) ON COMMIT DROP;
 TRUNCATE pg_temp._routed_player_todo;
 INSERT INTO pg_temp._routed_player_todo SELECT i.* FROM pg_temp._routed_player_items i
  WHERE NOT EXISTS(SELECT 1 FROM pg_temp._routed_player_done d WHERE d.period_id=i.period_id);
 CREATE TEMP TABLE IF NOT EXISTS _routed_player_now(period_id uuid PRIMARY KEY) ON COMMIT DROP;
 TRUNCATE pg_temp._routed_player_now;
 IF EXISTS(SELECT 1 FROM pg_temp._routed_player_todo i WHERE i.status IS DISTINCT FROM 'pending'
   OR EXISTS(SELECT 1 FROM public.rakeback_period_payouts pp WHERE pp.rakeback_period_id=i.period_id))
  OR EXISTS(SELECT 1 FROM public.union_settlement_rounds sr WHERE sr.union_id=p_union_id AND sr.round_no=3
   AND sr.period_start<p_period_end AND sr.period_end>p_period_start AND (sr.amount>0 OR sr.payees>0 OR sr.shortfalls>0))
 THEN RAISE EXCEPTION 'legacy_rakeback_payment_requires_reconciliation' USING ERRCODE='55000'; END IF;
 -- Discharge only owner-confirmed actual transfers AFTER the original whole
 -- source/certificate/refusal checks and BEFORE new wallet funding is planned.
 prior_saved_context:=current_setting('app.accounting_routing_context',true);
 PERFORM set_config('app.accounting_routing_context',scope.routing_context,true);
 FOR prior_item IN SELECT i.* FROM pg_temp._routed_player_todo i JOIN smarter_private.existing_rakeback_transfer_instructions q
  ON q.club_id=i.club_id AND q.beneficiary_id=i.user_id AND q.period_start=p_period_start AND q.period_end=p_period_end WHERE 'player'=ANY(q.roles)
  ORDER BY i.club_id,i.user_id,i.period_id LOOP
  prior_plan:=smarter_private.apply_existing_rakeback_transfer(p_scope_kind,p_scope_id,p_period_start,p_period_end,'player',prior_item.club_id,prior_item.user_id,prior_item.period_id,prior_item.certificate_id);
  IF prior_plan IS NULL THEN RAISE EXCEPTION 'existing_transfer_expected_player_instruction_required';END IF;
  INSERT INTO pg_temp._routed_player_done VALUES(prior_item.period_id)ON CONFLICT DO NOTHING;
  DELETE FROM pg_temp._routed_player_todo WHERE period_id=prior_item.period_id;
  UPDATE pg_temp._routed_player_items SET status='paid'WHERE period_id=prior_item.period_id;
 END LOOP;
 PERFORM set_config('app.accounting_routing_context',COALESCE(prior_saved_context,''),true);
 -- RAKEBACK IS PAID FROM WHERE COMMISSION LANDS (20261022, Dan). A real agent
 -- pays its players from its agent wallet (agents.agent_wallet_balance), where
 -- its weekly commission is credited. A share the certificate records for the
 -- club owner, or for no agent, is paid from the club bank, never from the
 -- owner's wallet. The certificate's payer identity is unchanged.
 CREATE TEMP TABLE IF NOT EXISTS _routed_player_funding(period_id uuid,payer_kind text,payer_user uuid,payer_entity uuid,owed numeric,club_id uuid,funded_from text,destination_kind text,typed_wallet boolean,PRIMARY KEY(period_id,payer_kind,payer_entity,destination_kind)) ON COMMIT DROP;
 TRUNCATE pg_temp._routed_player_funding;
 INSERT INTO pg_temp._routed_player_funding SELECT i.period_id,fp.payer_kind,fp.payer_user,fp.payer_entity,fp.owed,i.club_id,
  CASE WHEN fp.payer_kind='club' OR fp.payer_user IS NULL OR fp.payer_user=owner_club.owner_id THEN 'club_treasury' ELSE 'agent_wallet' END,fp.destination_kind,EXISTS(SELECT FROM public.accounting_rakeback_wallet_contracts wc WHERE wc.calculation_id=i.certificate_id)
 FROM pg_temp._routed_player_todo i JOIN public.clubs owner_club ON owner_club.id=i.club_id
 CROSS JOIN LATERAL smarter_private.rakeback_certificate_wallets(i.certificate_id)fp;
 IF EXISTS(SELECT 1 FROM pg_temp._routed_player_todo i WHERE i.owed IS DISTINCT FROM(SELECT sum(fp.owed)FROM pg_temp._routed_player_funding fp WHERE fp.period_id=i.period_id))
 THEN RAISE EXCEPTION 'routed_rakeback_payer_funding_not_conserved' USING ERRCODE='23514'; END IF;
 CREATE TEMP TABLE IF NOT EXISTS _routed_player_wallets(club_id uuid,user_id uuid,opening numeric,delta numeric,PRIMARY KEY(club_id,user_id)) ON COMMIT DROP;
 TRUNCATE pg_temp._routed_player_wallets;
 INSERT INTO pg_temp._routed_player_wallets(club_id,user_id,delta)
 SELECT f.club_id,i.user_id,sum(f.owed) FROM pg_temp._routed_player_funding f JOIN pg_temp._routed_player_todo i ON i.period_id=f.period_id WHERE f.owed>0 AND f.destination_kind='player_wallet' GROUP BY f.club_id,i.user_id;
 CREATE TEMP TABLE IF NOT EXISTS _routed_agent_wallets(club_id uuid,user_id uuid,opening numeric,delta numeric,PRIMARY KEY(club_id,user_id)) ON COMMIT DROP;
 TRUNCATE pg_temp._routed_agent_wallets;
 INSERT INTO pg_temp._routed_agent_wallets(club_id,user_id,delta)
 SELECT x.club_id,x.user_id,sum(x.delta) FROM(SELECT club_id,payer_user user_id,-owed delta FROM pg_temp._routed_player_funding WHERE funded_from='agent_wallet' UNION ALL SELECT f.club_id,i.user_id,f.owed FROM pg_temp._routed_player_funding f JOIN pg_temp._routed_player_todo i ON i.period_id=f.period_id WHERE f.destination_kind='agent_wallet')x GROUP BY x.club_id,x.user_id;
 PERFORM id FROM public.clubs WHERE id IN(SELECT club_id FROM pg_temp._routed_player_todo) ORDER BY id FOR NO KEY UPDATE;
 FOR r IN SELECT i.* FROM pg_temp._routed_player_todo i WHERE EXISTS(SELECT FROM pg_temp._routed_player_funding f WHERE f.period_id=i.period_id AND f.owed>0 AND f.destination_kind='player_wallet')
  AND NOT EXISTS(SELECT FROM public.club_members cm WHERE cm.club_id=i.club_id AND cm.user_id=i.user_id)
  ORDER BY i.club_id,i.user_id,i.period_id LOOP
  PERFORM smarter_private.preserve_historical_rakeback_wallet(r.period_id,r.certificate_id,p_period_start,p_period_end);
 END LOOP;
 PERFORM cm.user_id FROM public.club_members cm JOIN pg_temp._routed_player_wallets w ON w.club_id=cm.club_id AND w.user_id=cm.user_id
  ORDER BY cm.club_id,cm.user_id FOR NO KEY UPDATE OF cm;
 UPDATE pg_temp._routed_player_wallets w SET opening=cm.chip_balance FROM public.club_members cm WHERE cm.club_id=w.club_id AND cm.user_id=w.user_id;
 IF EXISTS(SELECT 1 FROM pg_temp._routed_player_wallets WHERE opening IS NULL OR opening<0 OR opening<>round(opening,2) OR opening::text IN('NaN','Infinity','-Infinity'))
 THEN RAISE EXCEPTION 'routed_rakeback_account_missing_or_invalid' USING ERRCODE='23514'; END IF;
 PERFORM a.id FROM public.agents a JOIN pg_temp._routed_agent_wallets w ON w.club_id=a.club_id AND w.user_id=a.user_id
  ORDER BY a.club_id,a.user_id FOR NO KEY UPDATE OF a;
 UPDATE pg_temp._routed_agent_wallets w SET opening=a.agent_wallet_balance FROM public.agents a WHERE a.club_id=w.club_id AND a.user_id=w.user_id;
 IF EXISTS(SELECT 1 FROM pg_temp._routed_agent_wallets WHERE opening IS NULL OR opening<0 OR opening<>round(opening,2) OR opening::text IN('NaN','Infinity','-Infinity'))
 THEN RAISE EXCEPTION 'routed_rakeback_agent_wallet_missing_or_invalid' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM(SELECT club_id,payer_user,sum(owed) owed FROM pg_temp._routed_player_funding WHERE funded_from='agent_wallet' GROUP BY club_id,payer_user) x
  JOIN pg_temp._routed_agent_wallets w ON w.club_id=x.club_id AND w.user_id=x.payer_user WHERE w.opening<x.owed)
 THEN RAISE EXCEPTION 'routed_rakeback_agent_funding_shortfall' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM(SELECT club_id,sum(owed) owed FROM pg_temp._routed_player_funding WHERE funded_from='club_treasury' GROUP BY club_id) x
  LEFT JOIN public.clubs bank ON bank.id=x.club_id WHERE bank.chip_treasury IS NULL OR bank.chip_treasury<x.owed
   OR bank.chip_treasury<>round(bank.chip_treasury,2) OR bank.chip_treasury::text IN('NaN','Infinity','-Infinity'))
 THEN RAISE EXCEPTION 'routed_rakeback_club_funding_shortfall' USING ERRCODE='23514'; END IF;
 -- Wallets above are locked: their opening already includes every prior return.
 -- Capture the same boundary for the receipt sum, including earlier calls in
 -- this transaction. Only this stage's subsequent return delta is subtracted.
 CREATE TEMP TABLE IF NOT EXISTS _routed_split_return_openings(club_id uuid,user_id uuid,returned numeric,PRIMARY KEY(club_id,user_id)) ON COMMIT DROP;
 TRUNCATE pg_temp._routed_split_return_openings;
 INSERT INTO pg_temp._routed_split_return_openings(club_id,user_id,returned)
 SELECT w.club_id,w.user_id,COALESCE(sum(lr.amount),0)
 FROM pg_temp._routed_player_wallets w LEFT JOIN public.ca_horse_club_split_late_returns lr
  ON lr.club_id=w.club_id AND lr.horse_id=w.user_id GROUP BY w.club_id,w.user_id;
 deleted_deferral:=current_setting('app.deleted_wallet_routing_stage',true);
 club_skip:=current_setting('app.ledger_autoskip_clubs',true);member_skip:=current_setting('app.ledger_autoskip_club_members',true);agent_skip:=current_setting('app.ledger_autoskip_agents',true);
 maintenance:=current_setting('app.ledger_maintenance',true);
 routing_context:=current_setting('app.accounting_routing_context',true);
 PERFORM set_config('app.accounting_routing_context',scope.routing_context,true);
 PERFORM set_config('app.deleted_wallet_routing_stage','rakeback',true);
 PERFORM set_config('app.ledger_autoskip_clubs','1',true);PERFORM set_config('app.ledger_autoskip_club_members','1',true);PERFORM set_config('app.ledger_autoskip_agents','1',true);
 v_stop:=CASE WHEN v_batched THEN LEAST(clock_timestamp()+interval '90 seconds',NULLIF(current_setting('app.weekly_accounting_scope_deadline',true),'')::timestamptz) ELSE clock_timestamp()+interval '90 seconds' END;
 FOR r IN SELECT * FROM pg_temp._routed_player_todo ORDER BY club_id,payer_user NULLS FIRST,user_id,period_id LOOP
   PERFORM smarter_private.weekly_payout_require_round(p_scope_kind,p_scope_id,p_period_start,p_period_end,3);
   amount:=r.owed;
   INSERT INTO public.rakeback_period_payouts(rakeback_period_id,club_id,user_id,user_rake_contribution,rakeback_pct,payout_amount,status,paid_at)
   VALUES(r.period_id,r.club_id,r.user_id,r.rake,round(r.rate*100,2),amount,'paid',now()) RETURNING id INTO payout_id;
  IF amount>0 THEN
   FOR g IN SELECT * FROM pg_temp._routed_player_funding WHERE period_id=r.period_id ORDER BY payer_kind,payer_entity,destination_kind LOOP
    amount:=g.owed;
    IF amount=0 THEN CONTINUE; END IF;
   IF g.destination_kind='agent_wallet' THEN
    SELECT agent_wallet_balance INTO player_before FROM public.agents WHERE club_id=r.club_id AND user_id=r.user_id;
   ELSE
    SELECT chip_balance INTO player_before FROM public.club_members WHERE club_id=r.club_id AND user_id=r.user_id;
   END IF;
   IF g.funded_from='club_treasury' THEN
    SELECT chip_treasury INTO payer_before FROM public.clubs WHERE id=r.club_id;
    UPDATE public.clubs SET chip_treasury=chip_treasury-amount WHERE id=r.club_id AND chip_treasury>=amount RETURNING chip_treasury INTO payer_after;
   ELSE
    SELECT agent_wallet_balance INTO payer_before FROM public.agents WHERE club_id=r.club_id AND user_id=g.payer_user;
    UPDATE public.agents SET agent_wallet_balance=agent_wallet_balance-amount,updated_at=now() WHERE club_id=r.club_id AND user_id=g.payer_user AND agent_wallet_balance>=amount RETURNING agent_wallet_balance INTO payer_after;
   END IF;
   IF g.destination_kind='agent_wallet' THEN
    UPDATE public.agents SET agent_wallet_balance=agent_wallet_balance+amount,updated_at=now() WHERE club_id=r.club_id AND user_id=r.user_id RETURNING agent_wallet_balance INTO player_after;
   ELSE
    UPDATE public.club_members SET chip_balance=chip_balance+amount,updated_at=now() WHERE club_id=r.club_id AND user_id=r.user_id RETURNING chip_balance INTO player_after;
   END IF;
   IF payer_after IS NULL OR player_after IS NULL OR payer_before-payer_after<>amount OR player_after-player_before<>amount
   THEN RAISE EXCEPTION 'routed_rakeback_transfer_not_conserved' USING ERRCODE='23514'; END IF;
   -- A debit of an agent wallet or the club bank is journalled by its leg below.
   INSERT INTO public.wallet_transactions(user_id,wallet_type,type,amount,category,description,balance_after,related_entity_id)
    VALUES(r.user_id,CASE WHEN g.destination_kind='agent_wallet' THEN 'BUSINESS' ELSE 'PLAYER' END,'credit',amount,'rakeback','Weekly rakeback received under recorded agreement',player_after,payout_id) RETURNING id INTO wallet_id;
   IF NOT g.typed_wallet AND r.payer_kind<>'split' THEN
   PERFORM set_config('app.ledger_maintenance','rakeback payout evidence pointer',true);
   UPDATE public.rakeback_period_payouts SET wallet_transaction_id=wallet_id WHERE id=payout_id;
   PERFORM set_config('app.ledger_maintenance',COALESCE(maintenance,''),true);
   END IF;
   INSERT INTO public.chip_ledger(performed_by,from_type,from_entity_id,to_type,to_entity_id,amount,category,club_id,union_id,description,idempotency_key,metadata,
    pre_from_balance,post_from_balance,pre_to_balance,post_to_balance)
    VALUES(COALESCE(auth.uid(),'2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid),CASE WHEN g.funded_from='club_treasury' THEN 'club_treasury' ELSE 'agent_wallet' END,
     CASE WHEN g.funded_from='club_treasury' THEN r.club_id ELSE g.payer_user END,g.destination_kind,r.user_id,amount,'rakeback',r.club_id,p_union_id,'Weekly rakeback from certified historical payer',
     CASE WHEN g.typed_wallet THEN 'round3-period:own-agent-v1:'||r.period_id::text||':payer:'||g.payer_kind||':'||g.payer_entity::text||':destination:'||g.destination_kind ELSE 'round3-period:v3:'||r.period_id::text||CASE WHEN r.payer_kind='split' THEN ':payer:'||g.payer_kind||':'||g.payer_entity::text ELSE '' END END,jsonb_build_object('routing_version',3,'accounting_scope_kind',p_scope_kind,'accounting_scope_id',p_scope_id,'period_id',r.period_id,'period_start',p_period_start,'period_end',p_period_end,
       'certificate_id',r.certificate_id,'source_fingerprint',r.fingerprint,'payout_id',payout_id,'wallet_transaction_id',wallet_id,'payee_role_at_transfer',CASE WHEN g.destination_kind='agent_wallet' THEN 'agent' ELSE 'player' END,
       'paid_from',g.funded_from,'owner_share_payer',CASE WHEN g.payer_kind='agent' AND g.funded_from='club_treasury' THEN g.payer_user END)||CASE WHEN g.typed_wallet THEN jsonb_build_object('wallet_destination_version','own-agent-v1','destination_kind',g.destination_kind) ELSE '{}'::jsonb END,
      payer_before,payer_after,player_before,player_after) RETURNING id INTO ledger_id;
   IF g.typed_wallet THEN
    INSERT INTO public.accounting_rakeback_wallet_transfers(payout_id,calculation_id,period_id,payer_kind,payer_entity_id,destination_kind,amount,ledger_id,wallet_transaction_id)
    VALUES(payout_id,r.certificate_id,r.period_id,g.payer_kind,g.payer_entity,g.destination_kind,amount,ledger_id,wallet_id);
   ELSIF r.payer_kind='split' THEN
    INSERT INTO public.accounting_rakeback_payer_transfers(payout_id,calculation_id,period_id,payer_kind,payer_entity_id,amount,ledger_id,wallet_transaction_id)
    VALUES(payout_id,r.certificate_id,r.period_id,g.payer_kind,g.payer_entity,amount,ledger_id,wallet_id);
   END IF;
   SELECT count(*) INTO receipt_count FROM public.settlement_invoices i WHERE i.source_ledger_id=ledger_id AND i.status='paid'
    AND i.chips_transferred AND i.message_sent AND i.net_amount=amount AND i.gross_amount=amount AND i.deductions=0;
   IF receipt_count<>1 THEN RAISE EXCEPTION 'routed_rakeback_invoice_delivery_incomplete' USING ERRCODE='23514'; END IF;
   END LOOP;
   paid:=paid+r.owed;payees:=payees+1;
  END IF;
  UPDATE public.rakeback_periods SET status='paid',paid_at=now() WHERE id=r.period_id;
  INSERT INTO pg_temp._routed_player_now VALUES(r.period_id);
  IF v_batched AND clock_timestamp()>v_stop
    AND NOT smarter_private.weekly_payout_owns_round(p_scope_kind,p_scope_id,p_period_start,p_period_end,3) THEN EXIT; END IF;
 END LOOP;
 SELECT count(*) INTO v_remaining FROM pg_temp._routed_player_todo t WHERE NOT EXISTS(SELECT 1 FROM pg_temp._routed_player_now n WHERE n.period_id=t.period_id);
 IF v_remaining>0 THEN
  -- A batch: every locked wallet must hold exactly what this batch paid it.
  UPDATE pg_temp._routed_player_wallets w SET delta=COALESCE((SELECT sum(x.delta) FROM(
   SELECT t.club_id,t.user_id,f.owed AS delta FROM pg_temp._routed_player_todo t JOIN pg_temp._routed_player_now n ON n.period_id=t.period_id JOIN pg_temp._routed_player_funding f ON f.period_id=t.period_id WHERE f.destination_kind='player_wallet'
   ) x
   WHERE x.club_id=w.club_id AND x.user_id=w.user_id),0);
  UPDATE pg_temp._routed_agent_wallets w SET delta=COALESCE((SELECT sum(x.delta)FROM(SELECT f.club_id,f.payer_user user_id,-f.owed delta FROM pg_temp._routed_player_funding f JOIN pg_temp._routed_player_now n ON n.period_id=f.period_id WHERE f.funded_from='agent_wallet' UNION ALL SELECT f.club_id,t.user_id,f.owed FROM pg_temp._routed_player_funding f JOIN pg_temp._routed_player_now n ON n.period_id=f.period_id JOIN pg_temp._routed_player_todo t ON t.period_id=f.period_id WHERE f.destination_kind='agent_wallet')x WHERE x.club_id=w.club_id AND x.user_id=w.user_id),0);
 END IF;
 PERFORM set_config('app.ledger_autoskip_clubs',COALESCE(club_skip,''),true);PERFORM set_config('app.ledger_autoskip_club_members',COALESCE(member_skip,''),true);PERFORM set_config('app.ledger_autoskip_agents',COALESCE(agent_skip,''),true);
 PERFORM set_config('app.deleted_wallet_routing_stage',COALESCE(deleted_deferral,''),true);
 CREATE TEMP TABLE IF NOT EXISTS _routed_split_returns(club_id uuid,user_id uuid,returned numeric,PRIMARY KEY(club_id,user_id)) ON COMMIT DROP;
 TRUNCATE pg_temp._routed_split_returns;
 INSERT INTO pg_temp._routed_split_returns(club_id,user_id,returned)
 SELECT lr.club_id,lr.horse_id,sum(lr.amount)-b.returned FROM public.ca_horse_club_split_late_returns lr
  JOIN pg_temp._routed_player_wallets pw ON pw.club_id=lr.club_id AND pw.user_id=lr.horse_id
  JOIN pg_temp._routed_split_return_openings b ON b.club_id=lr.club_id AND b.user_id=lr.horse_id
  GROUP BY lr.club_id,lr.horse_id,b.returned;
 IF EXISTS(SELECT 1 FROM pg_temp._routed_player_wallets w JOIN public.club_members cm ON cm.club_id=w.club_id AND cm.user_id=w.user_id
   LEFT JOIN pg_temp._routed_split_returns sr ON sr.club_id=w.club_id AND sr.user_id=w.user_id
   WHERE cm.chip_balance IS DISTINCT FROM w.opening+w.delta-COALESCE(sr.returned,0))
 THEN RAISE EXCEPTION 'routed_rakeback_final_balance_incorrect' USING ERRCODE='23514',
   DETAIL=left('final_balance_disagreements: '||COALESCE((SELECT jsonb_agg(jsonb_build_object('club',w.club_id,'user',w.user_id,'opening',w.opening,'delta',w.delta,'split_returned',COALESCE(sr.returned,0),'actual',cm.chip_balance,'off_by',round(cm.chip_balance-(w.opening+w.delta-COALESCE(sr.returned,0)),2)) ORDER BY abs(cm.chip_balance-(w.opening+w.delta-COALESCE(sr.returned,0))) DESC) FROM pg_temp._routed_player_wallets w JOIN public.club_members cm ON cm.club_id=w.club_id AND cm.user_id=w.user_id LEFT JOIN pg_temp._routed_split_returns sr ON sr.club_id=w.club_id AND sr.user_id=w.user_id WHERE cm.chip_balance IS DISTINCT FROM w.opening+w.delta-COALESCE(sr.returned,0))::text,'none'),3200); END IF;
 IF EXISTS(SELECT 1 FROM pg_temp._routed_agent_wallets w LEFT JOIN public.agents a ON a.club_id=w.club_id AND a.user_id=w.user_id
   WHERE a.agent_wallet_balance IS DISTINCT FROM w.opening+w.delta)
 THEN RAISE EXCEPTION 'routed_rakeback_final_agent_wallet_incorrect' USING ERRCODE='23514',
   DETAIL=left('final_balance_disagreements: '||COALESCE((SELECT jsonb_agg(jsonb_build_object('club',w.club_id,'user',w.user_id,'opening',w.opening,'delta',w.delta,'actual',a.agent_wallet_balance,'off_by',round(COALESCE(a.agent_wallet_balance,0)-(w.opening+w.delta),2)) ORDER BY abs(COALESCE(a.agent_wallet_balance,0)-(w.opening+w.delta)) DESC) FROM pg_temp._routed_agent_wallets w LEFT JOIN public.agents a ON a.club_id=w.club_id AND a.user_id=w.user_id WHERE a.agent_wallet_balance IS DISTINCT FROM w.opening+w.delta)::text,'none'),3200); END IF;
 -- All original transfer, invoice and net-wallet checks above still decide
 -- whether this stage may finish. Return only free net chips afterward,
 -- retaining published unpaid player obligations across bounded chunks.
 FOR v_deleted IN
  SELECT cm.club_id,cm.user_id FROM public.club_members cm
  JOIN public.profiles dp ON dp.id=cm.user_id AND dp.status='deleted'
  WHERE EXISTS(SELECT FROM pg_temp._routed_player_wallets w WHERE w.club_id=cm.club_id AND w.user_id=cm.user_id) AND EXISTS(SELECT FROM pg_temp._routed_player_todo t JOIN pg_temp._routed_player_now done ON done.period_id=t.period_id WHERE t.club_id=cm.club_id AND t.user_id=cm.user_id) ORDER BY cm.club_id,cm.user_id
 LOOP
  SELECT cm.chip_balance,coalesce(cm.held_chips,0),coalesce(cm.locked_chips,0)
   INTO STRICT v_deleted_before,v_deleted_held,v_deleted_locked FROM public.club_members cm
   WHERE cm.club_id=v_deleted.club_id AND cm.user_id=v_deleted.user_id;
  SELECT dwr_bank.chip_treasury INTO STRICT v_deleted_bank FROM public.clubs dwr_bank WHERE dwr_bank.id=v_deleted.club_id;
  v_deleted_return:=public.fn_ca_deleted_wallet_bank_return(v_deleted.club_id,v_deleted.user_id,'player_wallet');
  IF v_deleted_return->'success' IS DISTINCT FROM 'true'::jsonb
   OR v_deleted_return->>'reserved_rakeback' IS NULL OR (v_deleted_return->>'reserved_rakeback')::numeric<0
   OR (v_deleted_return->>'reserved_rakeback')::numeric::text IN('NaN','Infinity','-Infinity')
   OR (v_deleted_return->>'amount')::numeric IS DISTINCT FROM greatest(v_deleted_before-v_deleted_held-v_deleted_locked-(v_deleted_return->>'reserved_rakeback')::numeric,0)
   OR (v_deleted_return->>'player_chips')::numeric IS DISTINCT FROM (v_deleted_return->>'amount')::numeric
   OR (v_deleted_return->>'agent_chips')::numeric IS DISTINCT FROM 0::numeric
   OR NOT EXISTS(SELECT FROM public.club_members cm WHERE cm.club_id=v_deleted.club_id AND cm.user_id=v_deleted.user_id
     AND cm.chip_balance=v_deleted_before-(v_deleted_return->>'amount')::numeric
     AND coalesce(cm.held_chips,0)=v_deleted_held AND coalesce(cm.locked_chips,0)=v_deleted_locked)
   OR NOT EXISTS(SELECT FROM public.clubs dwr_bank WHERE dwr_bank.id=v_deleted.club_id AND dwr_bank.chip_treasury=v_deleted_bank+(v_deleted_return->>'amount')::numeric)
  THEN RAISE EXCEPTION 'deleted_weekly_net_bank_return_not_conserved' USING ERRCODE='23514'; END IF;
 END LOOP;
 FOR v_deleted IN
  SELECT a.club_id,a.user_id FROM public.agents a
  JOIN public.profiles dp ON dp.id=a.user_id AND dp.status='deleted'
  WHERE EXISTS(SELECT FROM pg_temp._routed_agent_wallets w WHERE w.club_id=a.club_id AND w.user_id=a.user_id)
   AND EXISTS(SELECT FROM pg_temp._routed_player_funding f JOIN pg_temp._routed_player_now done ON done.period_id=f.period_id
    WHERE f.club_id=a.club_id AND ((f.funded_from='agent_wallet' AND f.payer_user=a.user_id) OR(f.destination_kind='agent_wallet' AND EXISTS(SELECT FROM pg_temp._routed_player_todo t WHERE t.period_id=f.period_id AND t.user_id=a.user_id)))) ORDER BY a.club_id,a.user_id
 LOOP
  SELECT a.agent_wallet_balance INTO STRICT v_deleted_before FROM public.agents a
   WHERE a.club_id=v_deleted.club_id AND a.user_id=v_deleted.user_id;
  SELECT dwr_bank.chip_treasury INTO STRICT v_deleted_bank FROM public.clubs dwr_bank WHERE dwr_bank.id=v_deleted.club_id;
  v_deleted_return:=public.fn_ca_deleted_wallet_bank_return(v_deleted.club_id,v_deleted.user_id,'agent_wallet');
  IF v_deleted_return->'success' IS DISTINCT FROM 'true'::jsonb
   OR v_deleted_return->>'reserved_rakeback' IS NULL OR (v_deleted_return->>'reserved_rakeback')::numeric<0
   OR (v_deleted_return->>'reserved_rakeback')::numeric::text IN('NaN','Infinity','-Infinity')
   OR (v_deleted_return->>'amount')::numeric IS DISTINCT FROM greatest(v_deleted_before-(v_deleted_return->>'reserved_rakeback')::numeric,0)
   OR (v_deleted_return->>'agent_chips')::numeric IS DISTINCT FROM (v_deleted_return->>'amount')::numeric
   OR (v_deleted_return->>'player_chips')::numeric IS DISTINCT FROM 0::numeric
   OR NOT EXISTS(SELECT FROM public.agents a WHERE a.club_id=v_deleted.club_id AND a.user_id=v_deleted.user_id
     AND a.agent_wallet_balance=v_deleted_before-(v_deleted_return->>'amount')::numeric)
   OR NOT EXISTS(SELECT FROM public.clubs dwr_bank WHERE dwr_bank.id=v_deleted.club_id AND dwr_bank.chip_treasury=v_deleted_bank+(v_deleted_return->>'amount')::numeric)
  THEN RAISE EXCEPTION 'deleted_weekly_net_bank_return_not_conserved' USING ERRCODE='23514'; END IF;
 END LOOP;
 PERFORM set_config('app.accounting_routing_context',COALESCE(routing_context,''),true);

 IF v_remaining>0 THEN
  RETURN jsonb_build_object('success',false,'batch_committed',true,'round',3,'routing_version',3,'source_version',2,'scope_kind',p_scope_kind,'scope_id',p_scope_id,
   'periods',(SELECT count(*) FROM pg_temp._routed_player_items),'paid_periods',(SELECT count(*) FROM pg_temp._routed_player_done)+(SELECT count(*) FROM pg_temp._routed_player_now),
   'remaining',v_remaining,'source_fingerprint',fingerprint,'plan_used',v_plan_used);
 END IF;
 -- The round's totals include what earlier batches of it paid.
 SELECT COALESCE(sum(i.owed),0),count(*) INTO v_paid_before,v_payees_before FROM pg_temp._routed_player_items i
  JOIN pg_temp._routed_player_done d ON d.period_id=i.period_id WHERE i.owed>0;
 paid:=paid+v_paid_before;payees:=payees+v_payees_before;
 result:=jsonb_build_object('success',true,'round',3,'name','certified_payer_to_players','routing_version',3,'source_version',2,'source_contract_version',3,'scope_kind',p_scope_kind,'scope_id',p_scope_id,
  'amount',paid,'payees',payees,'shortfalls',0,'periods',(SELECT count(*) FROM pg_temp._routed_player_items),'detail','[]'::jsonb);
 result:=result||jsonb_build_object('existing_transfer_economic_plan',smarter_private.existing_rakeback_transfer_scope_economic_plan(p_scope_kind,p_scope_id,p_period_start,p_period_end,'player'),
  'existing_transfer_receipts',smarter_private.existing_rakeback_transfer_scope_receipts(p_scope_kind,p_scope_id,p_period_start,p_period_end,'player'));
 INSERT INTO public.accounting_routed_settlement_runs(union_id,standalone_club_id,period_start,period_end,round_no,source_fingerprint,result)
  VALUES(p_union_id,standalone_club,p_period_start,p_period_end,3,fingerprint,result);
 RETURN result;
END $function$

public.fn_spin_pool_follows_union_member.def:
CREATE OR REPLACE FUNCTION public.fn_spin_pool_follows_union_membership()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.union_id IS NOT NULL AND OLD.union_id IS DISTINCT FROM NEW.union_id THEN
    PERFORM public.fn_close_club_wallets_on_union_join(NEW.id, NEW.union_id);
  END IF;
  RETURN NEW;
END;
$function$

public.fn_sync_club_member_count().def:
CREATE OR REPLACE FUNCTION public.fn_sync_club_member_count()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_club uuid; v_union uuid;
BEGIN
  FOR v_club IN
    SELECT DISTINCT x FROM unnest(ARRAY[
      CASE WHEN TG_OP <> 'DELETE' THEN NEW.club_id END,
      CASE WHEN TG_OP <> 'INSERT' THEN OLD.club_id END
    ]) AS t(x) WHERE x IS NOT NULL
  LOOP
    PERFORM public.fn_apply_club_ladder(v_club);
    FOR v_union IN
      SELECT uc.union_id FROM public.union_clubs uc WHERE uc.club_id = v_club
    LOOP
      PERFORM public.fn_apply_union_ladder(v_union);
    END LOOP;
  END LOOP;
  RETURN COALESCE(NEW, OLD);
END;
$function$

public.fn_sync_club_staff_notice_group(p.def:
CREATE OR REPLACE FUNCTION public.fn_sync_club_staff_notice_group(p_club uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_conversation uuid; v_name text;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('club-staff-notice-group:'||p_club::text,0));
 SELECT name INTO v_name FROM public.clubs WHERE id=p_club;
 IF NOT FOUND THEN
  DELETE FROM public.social_conversation_participants WHERE conversation_id IN(SELECT conversation_id FROM public.club_messenger_staff_notice_groups WHERE club_id=p_club);
  RETURN;
 END IF;
 SELECT conversation_id INTO v_conversation FROM public.club_messenger_staff_notice_groups WHERE club_id=p_club;
 IF v_conversation IS NULL AND EXISTS(SELECT 1 FROM public.club_members m WHERE m.club_id=p_club AND public.fn_club_messenger_staff_role(p_club,m.user_id) IS NOT NULL) THEN
  INSERT INTO public.social_conversations(is_group,is_request,group_name) VALUES(true,false,v_name||' - Notice Board') RETURNING id INTO v_conversation;
  INSERT INTO public.club_messenger_staff_notice_groups(club_id,conversation_id) VALUES(p_club,v_conversation);
 END IF;
 IF v_conversation IS NULL THEN RETURN; END IF;
 DELETE FROM public.social_conversation_participants p WHERE p.conversation_id=v_conversation AND public.fn_club_messenger_staff_role(p_club,p.user_id) IS NULL;
 INSERT INTO public.social_conversation_participants(conversation_id,user_id)
 SELECT v_conversation,m.user_id FROM public.club_members m WHERE m.club_id=p_club AND public.fn_club_messenger_staff_role(p_club,m.user_id) IS NOT NULL
 AND NOT EXISTS(SELECT 1 FROM public.social_conversation_participants p WHERE p.conversation_id=v_conversation AND p.user_id=m.user_id);
END $function$

public.fn_terminal_tournament_evidence_i.def:
CREATE OR REPLACE FUNCTION public.fn_terminal_tournament_evidence_is_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tournament_id uuid;
  v_status text;
  v_receipted boolean := false;
  v_old_marker timestamptz;
  v_new_marker timestamptz;
BEGIN
 IF TG_OP='INSERT' AND TG_TABLE_NAME='chip_ledger' AND to_jsonb(NEW)->'metadata'->>'entry_kind'='launch_closing_position' THEN RETURN NEW; END IF;
  IF TG_OP<>'DELETE' AND public.fn_ca_legacy_fee_resolution_write_is_exact(TG_TABLE_NAME,TG_OP,CASE WHEN TG_OP='INSERT' THEN NULL ELSE to_jsonb(OLD) END,to_jsonb(NEW)) THEN RETURN NEW; END IF;
  IF TG_OP = 'INSERT' THEN
    v_tournament_id := NULLIF(to_jsonb(NEW)->>'tournament_id','')::uuid;
  ELSIF TG_OP = 'UPDATE' THEN
    IF NULLIF(to_jsonb(NEW)->>'tournament_id','')::uuid IS DISTINCT FROM
       NULLIF(to_jsonb(OLD)->>'tournament_id','')::uuid THEN
      RAISE EXCEPTION '% rows cannot move between tournaments',TG_TABLE_NAME
        USING ERRCODE = '55000';
    END IF;
    v_tournament_id := NULLIF(to_jsonb(OLD)->>'tournament_id','')::uuid;
  ELSE
    v_tournament_id := NULLIF(to_jsonb(OLD)->>'tournament_id','')::uuid;
  END IF;

  IF v_tournament_id IS NULL THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;
  IF TG_OP <> 'INSERT' AND to_jsonb(OLD) ? 'terminal_closed_at' THEN
    v_old_marker := NULLIF(to_jsonb(OLD)->>'terminal_closed_at','')::timestamptz;
  END IF;
  IF TG_OP <> 'DELETE' AND to_jsonb(NEW) ? 'terminal_closed_at' THEN
    v_new_marker := NULLIF(to_jsonb(NEW)->>'terminal_closed_at','')::timestamptz;
  END IF;
  IF TG_OP = 'INSERT' AND v_new_marker IS NOT NULL THEN
    RAISE EXCEPTION '% rows cannot supply a terminal marker',TG_TABLE_NAME
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP <> 'INSERT' AND v_old_marker IS NOT NULL THEN
    RAISE EXCEPTION 'terminal tournament % has immutable % evidence',
      v_tournament_id,TG_TABLE_NAME USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'UPDATE' AND v_new_marker IS DISTINCT FROM v_old_marker THEN
    IF public.fn_ca_terminal_marker_transition_is_exact(
         to_jsonb(OLD),to_jsonb(NEW),v_tournament_id) THEN
      RETURN NEW;
    END IF;
    RAISE EXCEPTION '% terminal marker transition is not canonical',TG_TABLE_NAME
      USING ERRCODE = '55000';
  END IF;
  -- A journal row is durable testimony from the instant it names a
  -- tournament. Refuse its UPDATE/DELETE without taking a child-to-parent
  -- lock; a row trigger already owns the child tuple at this point. INSERT is
  -- the only operation that takes the root lock, which preserves the
  -- parent-to-child order used by both terminal authorities.
  IF TG_TABLE_NAME = 'chip_ledger' AND TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'tournament chip ledger evidence is append-only'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'INSERT' THEN
    SELECT upper(COALESCE(t.status::text,'')) INTO v_status
      FROM public.tournaments t
     WHERE t.id = v_tournament_id
     FOR SHARE;
  ELSE
    SELECT upper(COALESCE(t.status::text,'')) INTO v_status
      FROM public.tournaments t
     WHERE t.id = v_tournament_id;
  END IF;
  SELECT EXISTS (
           SELECT 1 FROM public.tournament_terminal_settlements h
            WHERE h.tournament_id = v_tournament_id)
      OR EXISTS (
           SELECT 1 FROM public.tournament_satellite_settlements h
            WHERE h.tournament_id = v_tournament_id)
      OR EXISTS (
           SELECT 1 FROM public.tournament_cancellation_receipts h
            WHERE h.tournament_id = v_tournament_id)
    INTO v_receipted;
  IF v_status IN ('COMPLETED','CANCELLED','CANCELED')
     AND (TG_OP = 'INSERT' OR v_receipted) THEN
    RAISE EXCEPTION
      'terminal tournament % has immutable % evidence',
      v_tournament_id,TG_TABLE_NAME USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$

public.fn_terminal_wallet_transaction_is.def:
CREATE OR REPLACE FUNCTION public.fn_terminal_wallet_transaction_is_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_old_tournament_id uuid;
  v_new_tournament_id uuid;
  v_old_marker timestamptz;
  v_new_marker timestamptz;
  v_new_status text;
BEGIN
  IF TG_OP = 'UPDATE'
     AND NEW.related_entity_id IS DISTINCT FROM OLD.related_entity_id THEN
    RAISE EXCEPTION 'wallet transaction ownership is immutable'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP <> 'INSERT' THEN
    SELECT t.id INTO v_old_tournament_id FROM public.tournaments t
     WHERE t.id = OLD.related_entity_id;
  END IF;
  IF TG_OP <> 'DELETE' THEN
    SELECT t.id INTO v_new_tournament_id FROM public.tournaments t
     WHERE t.id = NEW.related_entity_id;
  END IF;
  IF TG_OP <> 'INSERT' THEN v_old_marker := OLD.terminal_closed_at; END IF;
  IF TG_OP <> 'DELETE' THEN v_new_marker := NEW.terminal_closed_at; END IF;
  IF TG_OP = 'INSERT' AND v_new_marker IS NOT NULL THEN
    RAISE EXCEPTION 'new wallet transaction cannot supply a terminal marker'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP <> 'INSERT' AND v_old_marker IS NOT NULL THEN
    RAISE EXCEPTION 'terminal wallet transaction evidence is immutable'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'UPDATE' AND v_new_marker IS DISTINCT FROM v_old_marker THEN
    IF public.fn_ca_terminal_marker_transition_is_exact(
         to_jsonb(OLD),to_jsonb(NEW),v_old_tournament_id) THEN
      RETURN NEW;
    END IF;
    RAISE EXCEPTION 'wallet transaction terminal marker transition is not canonical'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'INSERT' AND v_new_tournament_id IS NOT NULL THEN
    SELECT upper(COALESCE(t.status::text,'')) INTO v_new_status
      FROM public.tournaments t
     WHERE t.id = v_new_tournament_id FOR SHARE;
    IF v_new_status IN ('COMPLETED','CANCELLED','CANCELED') THEN
      RAISE EXCEPTION 'terminal wallet transaction evidence is immutable'
        USING ERRCODE = '55000';
    END IF;
  END IF;
  IF public.fn_ca_has_committed_tournament_receipt(v_old_tournament_id)
     OR public.fn_ca_has_committed_tournament_receipt(v_new_tournament_id) THEN
    RAISE EXCEPTION 'terminal wallet transaction evidence is immutable'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$

public.fn_union_pnl_capture_original_flo.def:
CREATE OR REPLACE FUNCTION public.fn_union_pnl_capture_original_flow()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE frame public.union_pnl_transaction_frames; scope jsonb;
BEGIN
 -- These are the original cash/table and tournament/liability journal legs.
 -- Other wallet transfers, rakeback and P&L payments are not poker winnings.
 IF NOT ((NEW.from_type IN ('player_wallet','club_treasury') AND NEW.to_type IN ('table_stack','prize_liability'))
  OR (NEW.to_type IN ('player_wallet','club_treasury') AND NEW.from_type IN ('table_stack','prize_liability'))) THEN RETURN NULL; END IF;
 frame:=public.fn_union_pnl_original_frame();
 IF NEW.tournament_id IS NOT NULL THEN
  SELECT jsonb_build_object('game_union_id',t.union_id,'host_club_id',t.club_id,'tournament_id',t.id,'is_private',t.is_private,'asset','chips','unit_scale',2)
  INTO scope FROM public.tournaments t WHERE t.id=NEW.tournament_id;
 ELSE
  SELECT jsonb_build_object('game_union_id',t.union_id,'host_club_id',t.club_id,'tournament_id',t.tournament_id,'is_private',t.is_private,'asset','chips','unit_scale',2)
  INTO scope FROM public.tables t WHERE t.id=NEW.table_id;
 END IF;
 INSERT INTO public.union_pnl_original_flows VALUES(NEW.id,frame.transaction_id,frame.observed_at,COALESCE(scope,'{}'),to_jsonb(NEW));
 RETURN NULL;
END $function$

public.lock_club_cashier_hierarchy_mutat.def:
CREATE OR REPLACE FUNCTION public.lock_club_cashier_hierarchy_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_old_club uuid := case when tg_op in ('UPDATE','DELETE') then old.club_id else null end;
  v_new_club uuid := case when tg_op in ('INSERT','UPDATE') then new.club_id else null end;
begin
  if v_old_club is not null and (v_new_club is null or v_old_club::text <= v_new_club::text) then
    perform pg_advisory_xact_lock(hashtextextended('cashier-hierarchy:'||v_old_club::text,0));
  end if;
  if v_new_club is not null and v_new_club is distinct from v_old_club then
    perform pg_advisory_xact_lock(hashtextextended('cashier-hierarchy:'||v_new_club::text,0));
  end if;
  if v_old_club is not null and v_new_club is not null and v_old_club::text > v_new_club::text then
    perform pg_advisory_xact_lock(hashtextextended('cashier-hierarchy:'||v_old_club::text,0));
  end if;
  return case when tg_op='DELETE' then old else new end;
end
$function$

