public.zz_chip_ledger_key_is_claimed_onc.def:
CREATE OR REPLACE FUNCTION public.zz_chip_ledger_key_is_claimed_once()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  /* 99.92% of legs carry no key and this does nothing for them. */
  IF NEW.idempotency_key IS NULL THEN
    RETURN NEW;
  END IF;

  /* No ON CONFLICT: the unique violation IS the refusal, and it must reach the
     caller exactly as ux_chip_ledger_idempotency_key's does today. Both are
     live until the cut; either one refusing is the correct outcome. */
  INSERT INTO public.chip_ledger_idem (idempotency_key, leg_id, created_at)
  VALUES (NEW.idempotency_key, NEW.id, COALESCE(NEW.created_at, now()));

  RETURN NEW;
END;
$function$

smarter_private.deleted_reserve_certific.def:
CREATE OR REPLACE FUNCTION smarter_private.deleted_reserve_certificate_payers(p_calculation bigint)
 RETURNS TABLE(payer_kind text, payer_user uuid, payer_entity uuid, owed numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE cert_tid tid;cert_xid text;v_contracts_version text;cached jsonb;cache_oid oid;
BEGIN
 -- Reports retain the original pure-reader contract in a read-only transaction.
 IF current_setting('transaction_read_only')::boolean THEN
  RETURN QUERY SELECT p.payer_kind,p.payer_user,p.payer_entity,p.owed FROM smarter_private.rakeback_certificate_payers(p_calculation)p;RETURN;
 END IF;
 -- Re-read physical row versions on every call. xmin alone is insufficient:
 -- updates performed in this same transaction retain xmin but replace ctid.
 SELECT c.ctid,c.xmin::text||'/'||c.cmin::text||'/'||c.tableoid::text||'/'||pg_catalog.pg_relation_filenode(c.tableoid)::text INTO STRICT cert_tid,cert_xid
 FROM public.accounting_rakeback_period_calculations c WHERE c.id=p_calculation;
 SELECT md5(count(*)::text||':'||coalesce(string_agg(g.tableoid::text||'/'||pg_catalog.pg_relation_filenode(g.tableoid)::text||'/'||g.ctid::text||'/'||g.xmin::text||'/'||g.cmin::text||'/'||md5(to_jsonb(g)::text),',' ORDER BY g.tableoid,g.ctid),''))
 INTO v_contracts_version FROM public.accounting_rakeback_payer_contracts g WHERE g.calculation_id=p_calculation;
 cache_oid:=to_regclass('pg_temp._deleted_reserve_payer_proofs');
 IF cache_oid IS NULL THEN
  CREATE TEMP TABLE _deleted_reserve_payer_proofs(calculation_id bigint PRIMARY KEY,certificate_tid tid NOT NULL,certificate_xid text NOT NULL,contracts_version text NOT NULL,payers jsonb NOT NULL)ON COMMIT DROP;
  REVOKE ALL ON TABLE pg_temp._deleted_reserve_payer_proofs FROM PUBLIC,anon,authenticated,service_role;
  cache_oid:=to_regclass('pg_temp._deleted_reserve_payer_proofs');
 END IF;
 IF NOT EXISTS(SELECT FROM pg_catalog.pg_class c WHERE c.oid=cache_oid AND c.relnamespace=pg_my_temp_schema()
   AND c.relkind='r'AND c.relpersistence='t'AND pg_get_userbyid(c.relowner)='postgres'AND NOT c.relrowsecurity)
  OR EXISTS(SELECT FROM pg_catalog.pg_trigger WHERE tgrelid=cache_oid AND NOT tgisinternal)
  OR EXISTS(SELECT FROM pg_catalog.pg_rewrite WHERE ev_class=cache_oid)
  OR (SELECT count(*)FROM pg_catalog.pg_attribute WHERE attrelid=cache_oid AND attnum>0 AND NOT attisdropped)<>5
  OR EXISTS(SELECT FROM(VALUES('calculation_id','bigint'::regtype),('certificate_tid','tid'::regtype),('certificate_xid','text'::regtype),('contracts_version','text'::regtype),('payers','jsonb'::regtype))v(n,t)
   WHERE NOT EXISTS(SELECT FROM pg_catalog.pg_attribute a WHERE a.attrelid=cache_oid AND a.attname=v.n AND a.atttypid=v.t AND a.attnotnull AND a.attnum>0 AND NOT a.attisdropped))
  OR EXISTS(SELECT FROM(VALUES('anon'),('authenticated'),('service_role'))roles(n)
   WHERE has_table_privilege(roles.n,cache_oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')OR has_any_column_privilege(roles.n,cache_oid,'SELECT,INSERT,UPDATE,REFERENCES'))
 THEN RAISE EXCEPTION 'deleted_reserve_payer_proof_temp_not_authoritative' USING ERRCODE='42501';END IF;
 SELECT p.payers INTO cached FROM pg_temp._deleted_reserve_payer_proofs p
 WHERE p.calculation_id=p_calculation AND p.certificate_tid=cert_tid AND p.certificate_xid=cert_xid AND p.contracts_version=v_contracts_version;
 IF NOT FOUND THEN
  -- The unchanged original validator is the sole producer of reusable output.
  SELECT coalesce(jsonb_agg(to_jsonb(p)ORDER BY p.payer_kind,p.payer_entity),'[]'::jsonb)INTO cached
  FROM smarter_private.rakeback_certificate_payers(p_calculation)p;
  INSERT INTO pg_temp._deleted_reserve_payer_proofs VALUES(p_calculation,cert_tid,cert_xid,v_contracts_version,cached)
  ON CONFLICT(calculation_id)DO UPDATE SET certificate_tid=EXCLUDED.certificate_tid,certificate_xid=EXCLUDED.certificate_xid,contracts_version=EXCLUDED.contracts_version,payers=EXCLUDED.payers;
 END IF;
 RETURN QUERY SELECT r.payer_kind,r.payer_user,r.payer_entity,r.owed FROM jsonb_to_recordset(cached)AS r(payer_kind text,payer_user uuid,payer_entity uuid,owed numeric);
END $function$

smarter_private.ensure_rakeback_payer_co.def:
CREATE OR REPLACE FUNCTION smarter_private.ensure_rakeback_payer_contracts(p_calculation bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE c public.accounting_rakeback_period_calculations%ROWTYPE;r public.rakeback_periods%ROWTYPE;plan jsonb;generated numeric;unrounded numeric;n bigint;distinct_n bigint;
BEGIN
 SELECT * INTO STRICT c FROM public.accounting_rakeback_period_calculations WHERE id=p_calculation;
 SELECT * INTO STRICT r FROM public.rakeback_periods WHERE id=c.period_id FOR UPDATE;
 IF r.status IS DISTINCT FROM 'pending' OR c.id IS DISTINCT FROM(SELECT max(x.id)FROM public.accounting_rakeback_period_calculations x WHERE x.period_id=r.id)
  OR c.accounting_version IS DISTINCT FROM 2 OR(c.club_id,c.player_id,c.period_start,c.period_end)IS DISTINCT FROM(r.club_id,r.user_id,r.period_start,r.period_end)
  OR(c.rake_generated,c.rake_generated,c.rakeback_amount,c.rakeback_amount,c.display_rate)IS DISTINCT FROM(r.rake_generated,r.total_rake_paid,r.rakeback_amount,r.rakeback_earned,r.rakeback_rate)
  OR c.source_fingerprint IS DISTINCT FROM md5(jsonb_build_object('allocations',c.source_allocations,'rake',c.rake_generated,'amount',c.rakeback_amount,'rate',c.display_rate)::text)
 THEN RAISE EXCEPTION 'rakeback_payer_certificate_not_current_pending' USING ERRCODE='23514';END IF;
 SELECT count(*),count(DISTINCT ROW(a->>'source_type',a->>'source_id')),sum((a->>'rake_credit')::numeric),sum((a->>'rake_credit')::numeric*(a->>'rate')::numeric)
 INTO n,distinct_n,generated,unrounded FROM jsonb_array_elements(c.source_allocations)a;
 IF n=0 OR n<>distinct_n OR generated IS DISTINCT FROM c.rake_generated OR round(unrounded,2)IS DISTINCT FROM c.rakeback_amount
  OR c.display_rate IS DISTINCT FROM(CASE WHEN generated>0 THEN round(unrounded/generated,4)ELSE 0 END)
  OR EXISTS(SELECT FROM jsonb_array_elements(c.source_allocations)a WHERE a->>'source_type'IS NULL OR a->>'source_type'NOT IN('cash_rake_accrual','tournament_fee_accrual')OR NULLIF(a->>'source_id','')IS NULL OR NULLIF(a->>'payer_user_id','')::uuid=c.player_id OR NULLIF(a->>'coordinator_union_id','')::uuid IS DISTINCT FROM c.coordinator_union_id)
 THEN RAISE EXCEPTION 'rakeback_payer_certificate_allocations_invalid' USING ERRCODE='23514';END IF;
 plan:=smarter_private.rakeback_payer_plan(c.source_allocations,c.rakeback_amount);
 IF c.payer_kind='split' THEN
  IF c.payer_user_id IS NOT NULL OR jsonb_array_length(plan)<2 THEN RAISE EXCEPTION 'split_rakeback_payers_required' USING ERRCODE='23514';END IF;
 ELSIF jsonb_array_length(plan)<>1 OR plan->0->>'payer_kind'IS DISTINCT FROM c.payer_kind OR NULLIF(plan->0->>'payer_user_id','')::uuid IS DISTINCT FROM c.payer_user_id
 THEN RAISE EXCEPTION 'rakeback_certificate_payer_disagrees' USING ERRCODE='23514';END IF;
 IF EXISTS(SELECT FROM public.accounting_rakeback_payer_contracts g LEFT JOIN jsonb_array_elements(plan)p ON g.payer_kind=p->>'payer_kind'AND g.payer_entity_id=COALESCE(NULLIF(p->>'payer_user_id','')::uuid,c.club_id)
 WHERE g.calculation_id=c.id AND(p IS NULL OR g.payer_user_id IS DISTINCT FROM NULLIF(p->>'payer_user_id','')::uuid OR g.amount IS DISTINCT FROM(p->>'amount')::numeric OR g.unrounded IS DISTINCT FROM(p->>'unrounded')::numeric OR g.rake IS DISTINCT FROM(p->>'rake')::numeric OR g.source_count IS DISTINCT FROM(p->>'source_count')::bigint OR g.source_fingerprint IS DISTINCT FROM c.source_fingerprint))
 THEN RAISE EXCEPTION 'existing_rakeback_payer_contract_disagrees' USING ERRCODE='23514';END IF;
 INSERT INTO public.accounting_rakeback_payer_contracts(calculation_id,payer_kind,payer_entity_id,payer_user_id,amount,unrounded,rake,source_count,source_fingerprint)
 SELECT c.id,p->>'payer_kind',COALESCE(NULLIF(p->>'payer_user_id','')::uuid,c.club_id),NULLIF(p->>'payer_user_id','')::uuid,(p->>'amount')::numeric,(p->>'unrounded')::numeric,(p->>'rake')::numeric,(p->>'source_count')::bigint,c.source_fingerprint
 FROM jsonb_array_elements(plan)p WHERE NOT EXISTS(SELECT FROM public.accounting_rakeback_payer_contracts g WHERE g.calculation_id=c.id AND g.payer_kind=p->>'payer_kind'AND g.payer_entity_id=COALESCE(NULLIF(p->>'payer_user_id','')::uuid,c.club_id));
END $function$

smarter_private.own_agent_destination_co.def:
CREATE OR REPLACE FUNCTION smarter_private.own_agent_destination_contract(p_contract jsonb, p_club uuid, p_player uuid, p_terms_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE member jsonb:=p_contract#>'{membership,terms}'; own jsonb; terms jsonb;
BEGIN
 IF member->>'role'NOT IN('super_agent','agent','sub_agent')OR member->>'role'IS NULL
  OR(member->>'player_rakeback_pct')::numeric IS DISTINCT FROM .70
  OR jsonb_array_length(p_contract->'tiers')<>0
  OR NOT EXISTS(SELECT FROM public.clubs c WHERE c.id=p_club AND c.owner_id=NULLIF(member->>'agent_id','')::uuid)
 THEN RETURN NULL;END IF;
 BEGIN own:=public.fn_accounting_agent_terms_at(p_club,p_player,p_terms_at);
 EXCEPTION WHEN SQLSTATE '55000' THEN
  IF SQLERRM IN('accounting_terms_not_observed','accounting_terms_not_active')THEN RETURN NULL;ELSE RAISE;END IF;
 END;
 terms:=own->'terms';
 IF terms IS NULL OR terms='null'::jsonb THEN RETURN NULL;END IF;
 IF terms->>'club_id'IS DISTINCT FROM p_club::text OR terms->>'user_id'IS DISTINCT FROM p_player::text
  OR terms->>'status'IS DISTINCT FROM'active'OR COALESCE(terms->>'role','')NOT IN('super_agent','agent','sub_agent')
  OR NULLIF(terms->>'id','')IS NULL OR(own->>'history_id')::bigint IS NULL OR(own->>'observed_at')::timestamptz>p_terms_at
 THEN RAISE EXCEPTION 'owner_agent_destination_contract_invalid' USING ERRCODE='55000';END IF;
 RETURN own;
END $function$

smarter_private.rakeback_certificate_wal.def:
CREATE OR REPLACE FUNCTION smarter_private.rakeback_certificate_wallets(p_calculation bigint)
 RETURNS TABLE(payer_kind text, payer_user uuid, payer_entity uuid, owed numeric, destination_kind text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE c public.accounting_rakeback_period_calculations%ROWTYPE;plan jsonb;
BEGIN
 SELECT*INTO STRICT c FROM public.accounting_rakeback_period_calculations WHERE id=p_calculation;
 IF NOT EXISTS(SELECT FROM jsonb_array_elements(c.source_allocations)a WHERE a?'destination_kind')THEN
  RETURN QUERY SELECT g.payer_kind,g.payer_user,g.payer_entity,g.owed,'player_wallet'::text FROM smarter_private.rakeback_certificate_payers(p_calculation)g;RETURN;
 END IF;
 -- Preserve and verify the original per-payer contract and cent allocation.
 PERFORM*FROM smarter_private.rakeback_certificate_payers(p_calculation);
 plan:=smarter_private.rakeback_wallet_plan(c.source_allocations,c.rakeback_amount);
 IF(SELECT count(*)FROM public.accounting_rakeback_wallet_contracts w WHERE w.calculation_id=c.id)<>jsonb_array_length(plan)
 OR EXISTS(SELECT FROM jsonb_array_elements(plan)p LEFT JOIN public.accounting_rakeback_wallet_contracts w ON w.calculation_id=c.id AND w.payer_kind=p->>'payer_kind'AND w.payer_entity_id=coalesce(NULLIF(p->>'payer_user_id','')::uuid,c.club_id)AND w.destination_kind=p->>'destination_kind'WHERE w.calculation_id IS NULL OR w.amount IS DISTINCT FROM(p->>'amount')::numeric OR w.unrounded IS DISTINCT FROM(p->>'unrounded')::numeric OR w.rake IS DISTINCT FROM(p->>'rake')::numeric OR w.source_count IS DISTINCT FROM(p->>'source_count')::bigint OR w.source_fingerprint IS DISTINCT FROM c.source_fingerprint OR w.payer_user_id=c.player_id)
 THEN RAISE EXCEPTION 'typed_wallet_contract_disagrees' USING ERRCODE='23514';END IF;
 RETURN QUERY SELECT w.payer_kind,w.payer_user_id,w.payer_entity_id,w.amount,w.destination_kind FROM public.accounting_rakeback_wallet_contracts w WHERE w.calculation_id=c.id ORDER BY w.payer_kind,w.payer_entity_id,w.destination_kind;
END $function$

smarter_private.rakeback_wallet_plan(p_a.def:
CREATE OR REPLACE FUNCTION smarter_private.rakeback_wallet_plan(p_allocations jsonb, p_amount numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE original jsonb;result jsonb;
BEGIN
 original:=smarter_private.rakeback_payer_plan(p_allocations,p_amount);
 IF EXISTS(SELECT FROM jsonb_array_elements(p_allocations)a WHERE a?'destination_kind'AND(a->>'destination_kind'IS DISTINCT FROM'agent_wallet'OR a->>'interpretation_version'IS DISTINCT FROM'own-agent-v1'OR jsonb_typeof(a->'destination_agreement')IS DISTINCT FROM'object'))THEN RAISE EXCEPTION 'rakeback_wallet_destination_invalid' USING ERRCODE='23514';END IF;
 WITH groups AS(
  SELECT a->>'payer_kind'kind,NULLIF(a->>'payer_user_id','')::uuid payer,coalesce(a->>'destination_kind','player_wallet')destination,
   sum((a->>'rake_credit')::numeric)rake,sum((a->>'rake_credit')::numeric*(a->>'rate')::numeric)unrounded,count(*)n
  FROM jsonb_array_elements(p_allocations)a GROUP BY 1,2,3
 ),cents AS(
  SELECT g.*,floor(g.unrounded*100)whole,row_number()OVER(PARTITION BY g.kind,g.payer ORDER BY g.unrounded*100-floor(g.unrounded*100)DESC,g.destination)rank,
   (p->>'amount')::numeric*100-sum(floor(g.unrounded*100))OVER(PARTITION BY g.kind,g.payer)extra
  FROM groups g JOIN jsonb_array_elements(original)p ON p->>'payer_kind'=g.kind AND NULLIF(p->>'payer_user_id','')::uuid IS NOT DISTINCT FROM g.payer
 )SELECT jsonb_agg(jsonb_build_object('payer_kind',kind,'payer_user_id',payer,'destination_kind',destination,'rake',rake,'unrounded',unrounded,'source_count',n,'amount',(whole+CASE WHEN rank<=extra THEN 1 ELSE 0 END)/100)ORDER BY kind,payer NULLS FIRST,destination)INTO result FROM cents;
 IF(SELECT sum((p->>'amount')::numeric)FROM jsonb_array_elements(result)p)IS DISTINCT FROM p_amount THEN RAISE EXCEPTION 'rakeback_wallet_plan_not_conserved' USING ERRCODE='23514';END IF;
 RETURN result;
END $function$

smarter_private.record_rakeback_wallet_c.def:
CREATE OR REPLACE FUNCTION smarter_private.record_rakeback_wallet_contracts()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE allocation jsonb;actual jsonb;authority jsonb;plan jsonb;n int;
BEGIN
 IF NOT EXISTS(SELECT FROM jsonb_array_elements(NEW.source_allocations)a WHERE a?'destination_kind')THEN RETURN NULL;END IF;
 IF NOT EXISTS(SELECT FROM public.rakeback_periods r WHERE r.id=NEW.period_id AND r.status='pending')THEN RAISE EXCEPTION 'typed_wallet_certificate_requires_unpaid_period' USING ERRCODE='23514';END IF;
 FOR allocation IN SELECT a FROM jsonb_array_elements(NEW.source_allocations)a WHERE a?'destination_kind'LOOP
  SELECT count(*),(jsonb_agg(to_jsonb(s)))->0 INTO n,actual FROM public.accounting_payable_earning_sources s WHERE s.source_type=allocation->>'source_type'AND s.source_id=(allocation->>'source_id')::uuid;
  IF n<>1 OR actual->>'club_id'IS DISTINCT FROM NEW.club_id::text OR actual->>'player_id'IS DISTINCT FROM NEW.player_id::text THEN RAISE EXCEPTION 'typed_wallet_source_identity_changed' USING ERRCODE='23514';END IF;
  authority:=smarter_private.own_agent_destination_contract(actual->'contract',NEW.club_id,NEW.player_id,(allocation->>'agreement_at')::timestamptz);
  IF authority IS NULL OR authority IS DISTINCT FROM allocation->'destination_agreement'OR allocation->>'interpretation_version'IS DISTINCT FROM'own-agent-v1'OR allocation->>'destination_kind'IS DISTINCT FROM'agent_wallet'OR(allocation->>'rate')::numeric IS DISTINCT FROM .70 OR actual#>>'{contract,membership,terms,role}'NOT IN('super_agent','agent','sub_agent')THEN RAISE EXCEPTION 'typed_wallet_historical_destination_not_observed' USING ERRCODE='23514';END IF;
 END LOOP;
 plan:=smarter_private.rakeback_wallet_plan(NEW.source_allocations,NEW.rakeback_amount);
 INSERT INTO public.accounting_rakeback_wallet_contracts(calculation_id,payer_kind,payer_entity_id,payer_user_id,destination_kind,amount,unrounded,rake,source_count,source_fingerprint)
 SELECT NEW.id,p->>'payer_kind',coalesce(NULLIF(p->>'payer_user_id','')::uuid,NEW.club_id),NULLIF(p->>'payer_user_id','')::uuid,p->>'destination_kind',(p->>'amount')::numeric,(p->>'unrounded')::numeric,(p->>'rake')::numeric,(p->>'source_count')::bigint,NEW.source_fingerprint FROM jsonb_array_elements(plan)p;
 RETURN NULL;
END $function$

smarter_private.weekly_payout_fund_agent.def:
CREATE OR REPLACE FUNCTION smarter_private.weekly_payout_fund_agent_shortfalls(p_run uuid, p_kind text, p_id uuid, p_from timestamp with time zone, p_to timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE d_from date:=(p_from AT TIME ZONE 'America/Los_Angeles')::date; s record; res jsonb; out jsonb:='[]'::jsonb; saved text:=current_setting('request.jwt.claims',true); saved_sub text:=current_setting('request.jwt.claim.sub',true);
BEGIN
 FOR s IN
  WITH f AS (SELECT c.club_id, fp.payer_user, fp.owed FROM public.accounting_rakeback_period_calculations c JOIN public.rakeback_periods rp ON rp.id=c.period_id
    CROSS JOIN LATERAL smarter_private.rakeback_certificate_wallets(c.id) fp
    JOIN public.clubs cl ON cl.id=c.club_id
    WHERE rp.period_start=d_from AND rp.status='pending' AND c.payer_kind<>'club'
     AND ((p_kind='union' AND c.coordinator_union_id=p_id) OR (p_kind='club' AND c.club_id=p_id AND c.coordinator_union_id IS NULL))
     AND fp.payer_kind<>'club' AND fp.payer_user IS NOT NULL AND fp.payer_user<>cl.owner_id AND fp.owed>0)
  SELECT f.club_id, f.payer_user, round(sum(f.owed),2) owed, a.agent_wallet_balance bal, cl.owner_id
  FROM f JOIN public.agents a ON a.club_id=f.club_id AND a.user_id=f.payer_user JOIN public.clubs cl ON cl.id=f.club_id
  GROUP BY f.club_id,f.payer_user,a.agent_wallet_balance,cl.owner_id HAVING round(sum(f.owed),2)>a.agent_wallet_balance
 LOOP
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',s.owner_id,'role','authenticated')::text,true);
  PERFORM set_config('request.jwt.claim.sub',s.owner_id::text,true);
  res:=public.fn_club_bank_send(s.club_id,s.payer_user,round(s.owed-s.bal,2),'agent_wallet',
    'Weekly rakeback funding: agent wallet short for players (week ending '||to_char(p_to AT TIME ZONE 'America/Chicago','Mon DD')||')',
    md5(p_run::text||':'||s.club_id::text||':'||s.payer_user::text)::uuid);
  IF COALESCE(res->>'success','false')<>'true' THEN RAISE EXCEPTION 'weekly_payout_agent_funding_refused %',res::text; END IF;
  out:=out||jsonb_build_array(jsonb_build_object('club_id',s.club_id,'agent_user_id',s.payer_user,'owed',s.owed,'wallet_before',s.bal,'funded',round(s.owed-s.bal,2)));
 END LOOP;
 PERFORM set_config('request.jwt.claims',COALESCE(saved,''),true);
 PERFORM set_config('request.jwt.claim.sub',COALESCE(saved_sub,''),true);
 RETURN out;
END $function$
